    /// Sets the source file and content for error reporting
    pub fn set_source(&mut self, file: String, content: &str) {
        self.source_file = Some(file);
        self.source_lines = content.lines().map(|s| s.to_string()).collect();
    }

    /// Reports a runtime error with source location
    #[allow(dead_code)]
    fn report_error(&self, error: KujoError) {
        eprintln!("{}", error);
    }

    /// Gets the source line at a given line number (1-indexed)
    #[allow(dead_code)]
    fn get_source_line(&self, line: usize) -> Option<String> {
        if line > 0 && line <= self.source_lines.len() {
            Some(self.source_lines[line - 1].clone())
        } else {
            None
        }
    }

    /// Sets the output sink for print statements (used for testing)
    #[allow(dead_code)]
    pub fn set_output(&mut self, output: Arc<Mutex<Vec<u8>>>) {
        self.output = Some(output);
    }

    fn active_capture_index(&self, captured: &Arc<Mutex<Environment>>) -> Option<usize> {
        self.environment_activations.iter().rposition(|frame| {
            frame.capture.as_ref().is_some_and(|(owner, _)| Arc::ptr_eq(owner, captured))
        })
    }

    // A shared-global transition moves only the global scope. The captured locals
    // remain in the first suspended caller; its globals live up to the next captured
    // transition (or in the current environment if there is no such transition).
    fn capture_global_owner_index(&self, index: usize) -> Option<usize> {
        self.environment_activations.iter().enumerate().skip(index + 1).find_map(
            |(index, frame)| {
                (frame.capture.is_some()
                    && !matches!(
                        frame.globals,
                        CapturedGlobals::TaskCaller | CapturedGlobals::RecursiveCaller
                    ))
                .then_some(index)
            },
        )
    }

    fn active_capture_snapshot(&mut self, index: usize) -> Environment {
        let count = self.environment_activations[index].capture.as_ref().unwrap().1;
        let locals = self
            .environment_activations
            .get(index + 1)
            .map(|frame| &frame.caller)
            .unwrap_or(&self.env);
        let globals = self
            .capture_global_owner_index(index)
            .map(|owner| &self.environment_activations[owner].caller)
            .unwrap_or(&self.env);
        let mut snapshot = locals.capture_prefix_snapshot(count, &mut self.capture_storage_pool);
        if !std::ptr::eq(locals, globals) {
            snapshot.copy_global_scope_from(globals);
        }
        snapshot
    }

    fn restore_active_capture(&mut self, index: usize, completed: &Environment) {
        let count = self.environment_activations[index].capture.as_ref().unwrap().1;
        let globals = self.capture_global_owner_index(index);
        let locals = self
            .environment_activations
            .get_mut(index + 1)
            .map(|frame| &mut frame.caller)
            .unwrap_or(&mut self.env);
        locals.restore_capture_locals(completed, count);
        let globals = match globals {
            Some(owner) => &mut self.environment_activations[owner].caller,
            None => &mut self.env,
        };
        globals.copy_global_scope_from(completed);
    }

    // Shared-global helpers, generators and foreign VM callbacks can change a
    // suspended capture. Keep the full synchronization path for these boundaries.
    fn invalidate_capture_observations(&mut self) {
        self.env.invalidate_capture_observation();
        for frame in &mut self.environment_activations {
            frame.caller.invalidate_capture_observation();
        }
    }

    fn capture_globals_checkpoint(&self) -> (Option<TaskCaptureGlobals>, usize) {
        let previous = self.task_capture_globals.clone();
        let count = previous.as_ref().map_or(0, |globals| {
            globals.lock().unwrap_or_else(|poisoned| poisoned.into_inner()).len()
        });
        (previous, count)
    }

    fn restore_capture_globals_checkpoint(
        &mut self,
        checkpoint: (Option<TaskCaptureGlobals>, usize),
    ) {
        let (previous, count) = checkpoint;
        if let Some(globals) = &previous {
            globals.lock().unwrap_or_else(|poisoned| poisoned.into_inner()).truncate(count);
        }
        self.task_capture_globals = previous;
    }

    // Inspect/copy the saved namespace without cloning a temporary Environment.
    // Callers perform only internal reads/copies: never invoke language code here.
    fn with_task_capture_globals<R>(
        &self,
        owner: &Arc<Mutex<Environment>>,
        read: impl FnOnce(&Environment) -> R,
    ) -> Option<R> {
        self.task_capture_globals.as_ref().and_then(|globals| {
            globals
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .iter()
                .find(|(capture, _)| Arc::ptr_eq(capture, owner))
                .map(|(_, environment)| read(environment))
        })
    }

    fn remember_task_capture_globals(
        &mut self,
        owner: &Arc<Mutex<Environment>>,
        snapshot: &Environment,
    ) {
        let globals =
            self.task_capture_globals.get_or_insert_with(|| Arc::new(Mutex::new(Vec::new())));
        let mut globals = globals.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some((_, environment)) =
            globals.iter_mut().find(|(capture, _)| Arc::ptr_eq(capture, owner))
        {
            environment.copy_global_scope_from(snapshot);
        } else {
            globals.push((owner.clone(), snapshot.global_snapshot()));
        }
    }

    fn copy_task_bridge_globals(&self, environment: &mut Environment, refresh: bool) -> bool {
        if self.task_cancellation.is_none() {
            return false;
        }
        let Some(globals) = &self.vm_globals else { return false };
        let globals = globals.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        if !environment.shares_global_source(&globals) {
            return false;
        }
        if refresh {
            environment.copy_global_scope_from(&globals);
        }
        true
    }

    fn publish_task_bridge_globals(&self, owners: &[Arc<Mutex<Environment>>]) {
        if self.task_cancellation.is_none() {
            return;
        }
        let Some(globals) = &self.vm_globals else { return };
        let mut globals = globals.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        if self.env.shares_global_source(&globals) {
            globals.copy_global_scope_from(&self.env);
            return;
        }
        // A module call can suspend the caller namespace. Select the newest
        // active capture of that namespace, never the module's same-named bindings.
        for owner in owners {
            let copied = self.with_task_capture_globals(owner, |snapshot| {
                if snapshot.shares_global_source(&globals) {
                    globals.copy_global_scope_from(snapshot);
                    true
                } else {
                    false
                }
            });
            if copied == Some(true) {
                break;
            }
        }
    }

    // A bytecode callback can enter another Interpreter instance. Publish only the
    // newest activation of each shared capture before crossing that boundary, then
    // refresh it afterward, including on an error return. Caller-only scopes remain
    // in their owning activation and separately created captures retain identity.
    fn publish_active_captures_for_bridge(&mut self) -> Vec<Arc<Mutex<Environment>>> {
        self.invalidate_capture_observations();
        let mut owners: Vec<Arc<Mutex<Environment>>> = Vec::new();
        for index in (0..self.environment_activations.len()).rev() {
            let Some((owner, _)) = &self.environment_activations[index].capture else {
                continue;
            };
            if owners.iter().any(|existing| Arc::ptr_eq(existing, owner)) {
                continue;
            }
            let owner = owner.clone();
            let snapshot = self.active_capture_snapshot(index);
            if self.task_cancellation.is_some() {
                self.remember_task_capture_globals(&owner, &snapshot);
                owner
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .merge_task_capture_writes(&snapshot);
            } else if snapshot.has_live_capture() {
                owner
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .copy_global_scope_from(&snapshot);
            } else {
                *owner.lock().unwrap_or_else(|poisoned| poisoned.into_inner()) = snapshot;
            }
            owners.push(owner);
        }
        self.publish_task_bridge_globals(&owners);
        owners
    }

    fn refresh_active_captures_after_bridge(&mut self, owners: Vec<Arc<Mutex<Environment>>>) {
        for owner in owners {
            if let Some(index) = self.active_capture_index(&owner) {
                let mut completed =
                    owner.lock().unwrap_or_else(|poisoned| poisoned.into_inner()).clone();
                if !self.copy_task_bridge_globals(&mut completed, true) {
                    self.with_task_capture_globals(&owner, |globals| {
                        completed.copy_global_scope_from(globals);
                    });
                }
                self.restore_active_capture(index, &completed);
            }
        }
        // Global-only task functions have no captured activation to refresh.
        // Callback writes, including writes before a caught error, remain task-local.
        if self.task_cancellation.is_some() {
            if let Some(globals) = &self.vm_globals {
                let globals = globals.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
                if self.env.shares_global_source(&globals) {
                    self.env.copy_global_scope_from(&globals);
                }
            }
        }
    }

    fn enter_captured_function_environment(
        &mut self,
        captured: &Arc<Mutex<Environment>>,
        body: &value::FunctionBodyRef,
        params: &[String],
        args: &[Value],
    ) {
        if self.task_cancellation.is_none() && self.active_capture_index(captured).is_none() {
            if let Some(proof) = body.read_capture_proof(args) {
                let projected =
                    captured.lock().unwrap_or_else(|p| p.into_inner()).project_capture_name_iter(
                        proof.required_parameters.iter(),
                        params,
                        proof.primitive_arguments,
                        &mut self.capture_storage_pool,
                    );
                if let Some(mut environment) = projected {
                    environment.observe_capture_writes(false);
                    let count = environment.scopes.len();
                    let caller = std::mem::replace(&mut self.env, environment);
                    self.environment_activations.push(EnvironmentActivation {
                        publication_policy: 0,
                        nested_spill_hint: Default::default(),
                        insertion_bound: 0,
                        capture: Some((captured.clone(), count)),
                        caller,
                        globals: CapturedGlobals::Snapshot,
                    });
                    return;
                }
            }
        }
        let may_check_nested =
            self.task_cancellation.is_none() && self.active_capture_index(captured).is_none();
        let allow_boxed_array = may_check_nested && body.can_defer_boxed_array();
        self.enter_captured_environment(captured);
        let allow_multi_key = may_check_nested
            && self
                .environment_activations
                .last()
                .is_some_and(|frame| frame.globals == CapturedGlobals::Snapshot)
            && body.can_batch_dictionary_writes(params, args, &self.env);
        let insertion_bound =
            if allow_multi_key { body.dictionary_insertion_bound(params, args) } else { 0 };
        let nested_spill_hint = if may_check_nested
            && self
                .environment_activations
                .last()
                .is_some_and(|frame| frame.globals == CapturedGlobals::Snapshot)
        {
            body.can_batch_nested_dictionary_writes(params, args, &self.env)
        } else {
            Default::default()
        };
        let array_batch_capacity = if may_check_nested
            && self
                .environment_activations
                .last()
                .is_some_and(|frame| frame.globals == CapturedGlobals::Snapshot)
        {
            array_batch_proof::eligible(body, params, args, &self.env)
        } else {
            0
        };
        if let Some(frame) = self.environment_activations.last_mut() {
            frame.nested_spill_hint = nested_spill_hint;
            frame.insertion_bound = if frame.globals == CapturedGlobals::Snapshot {
                // The array proof caps distinct writes by the actual owner length.
                // A dictionary's insertion count can exceed that cap on rewrites.
                if array_batch_capacity > 0 {
                    array_batch_capacity
                } else {
                    insertion_bound
                }
            } else {
                0
            };
            frame.publication_policy = if frame.globals == CapturedGlobals::Snapshot {
                u8::from(allow_multi_key)
                    | (u8::from(allow_boxed_array) << 1)
                    | (u8::from(array_batch_capacity > 0) << 2)
            } else {
                0
            };
        }
    }

    fn enter_captured_environment(&mut self, captured: &Arc<Mutex<Environment>>) {
        let active = self.active_capture_index(captured);
        // Direct synchronous reentry can transfer its private capture prefix.
        // Live captured values stay in their public owner; only private maps
        // move. Caller parameters remain outside the transferred prefix.
        if self.task_cancellation.is_none()
            && active.is_some_and(|index| {
                index + 1 == self.environment_activations.len()
                    && (self.environment_activations[index].capture.as_ref().unwrap().1 == 1
                        || self.env.has_live_capture())
            })
        {
            let count = self.environment_activations[active.unwrap()].capture.as_ref().unwrap().1;
            let mut environment =
                self.env.recursive_prefix_environment(count, &mut self.capture_storage_pool);
            environment.swap_capture_prefix(&mut self.env, count);
            environment.observe_capture_writes(true);
            let caller = std::mem::replace(&mut self.env, environment);
            self.environment_activations.push(EnvironmentActivation {
                publication_policy: 0,
                nested_spill_hint: Default::default(),
                insertion_bound: 0,
                capture: Some((captured.clone(), count)),
                caller,
                globals: CapturedGlobals::RecursiveCaller,
            });
            return;
        }
        // A foreign capture can suspend this namespace between reentries. Move
        // its private prefix when globals and live locals share one suspended
        // frame, or restore split local/global owners independently. The
        // foreign caller stays in place, and the return destination is recoverable
        // from the remaining stack, so ordinary frames need no extra index field.
        // Public owners still retain their published values.
        if self.task_cancellation.is_none() {
            if let Some(index) = active {
                let count = self.environment_activations[index].capture.as_ref().unwrap().1;
                if let Some(owner) = self.capture_global_owner_index(index) {
                    let source = &mut self.environment_activations[owner].caller;
                    if count == 1 || (owner == index + 1 && source.has_live_capture()) {
                        let mut environment = if count == 1 {
                            source.recursive_global_environment(&mut self.capture_storage_pool)
                        } else {
                            source
                                .recursive_prefix_environment(count, &mut self.capture_storage_pool)
                        };
                        environment.swap_capture_prefix(source, count);
                        environment.observe_capture_writes(true);
                        let caller = std::mem::replace(&mut self.env, environment);
                        self.environment_activations.push(EnvironmentActivation {
                            publication_policy: 0,
                            nested_spill_hint: Default::default(),
                            insertion_bound: 0,
                            capture: Some((captured.clone(), count)),
                            caller,
                            globals: CapturedGlobals::RecursiveOwner,
                        });
                        return;
                    }
                    if owner != index + 1
                        && self.environment_activations[index + 1].caller.has_live_capture()
                    {
                        let locals = &mut self.environment_activations[index + 1].caller;
                        let mut environment = locals
                            .recursive_prefix_environment(count, &mut self.capture_storage_pool);
                        environment.transfer_capture_locals_from(locals, count);
                        environment.publish_global_scope_from(
                            &mut self.environment_activations[owner].caller,
                        );
                        environment.observe_capture_writes(true);
                        let caller = std::mem::replace(&mut self.env, environment);
                        self.environment_activations.push(EnvironmentActivation {
                            publication_policy: 0,
                            nested_spill_hint: Default::default(),
                            insertion_bound: 0,
                            capture: Some((captured.clone(), count)),
                            caller,
                            globals: CapturedGlobals::RecursiveSplitOwner,
                        });
                        return;
                    }
                }
            }
        }
        let mut environment = match active {
            Some(index) => self.active_capture_snapshot(index),
            None => {
                Environment::capture_activation_with_pool(captured, &mut self.capture_storage_pool)
            }
        };
        let globals = if self.task_cancellation.is_none() {
            CapturedGlobals::Snapshot
        } else if environment.shares_global_source(&self.env) {
            // Keep the task's live global map moving through captured calls.
            // Copying it on every invocation scales with unrelated global names.
            environment.swap_global_scope(&mut self.env);
            CapturedGlobals::TaskCaller
        } else if self.copy_task_bridge_globals(&mut environment, active.is_none()) {
            // Reentry already has the live activation's globals. A new activation
            // observes the callback VM's newer writes before a saved override.
            CapturedGlobals::TaskBridge
        } else if self
            .with_task_capture_globals(captured, |globals| {
                if active.is_none() {
                    environment.copy_global_scope_from(globals);
                }
            })
            .is_some()
        {
            CapturedGlobals::TaskCapture
        } else {
            CapturedGlobals::Snapshot
        };
        environment.observe_capture_writes(active.is_some());
        // Task aliases may finish independently. Publish only this invocation's
        // writes, never its stale snapshot of another task's captured bindings.
        if self.task_cancellation.is_some() {
            environment.track_capture_writes();
        } else if active.is_none() {
            environment.enable_indexed_publication();
        }
        let count = environment.scopes.len();
        let caller = std::mem::replace(&mut self.env, environment);
        self.environment_activations.push(EnvironmentActivation {
            publication_policy: 0,
            nested_spill_hint: Default::default(),
            insertion_bound: 0,
            capture: Some((captured.clone(), count)),
            caller,
            globals,
        });
    }

    fn leave_captured_environment(&mut self, publish: bool) {
        let frame = self.environment_activations.pop().expect("captured activation exists");
        let (captured, count) = frame.capture.expect("captured activation has an owner");
        let mut completed = std::mem::replace(&mut self.env, frame.caller);
        let changed = !completed.capture_is_unchanged();
        if frame.globals == CapturedGlobals::RecursiveSplitOwner {
            let active = self.active_capture_index(&captured).expect("recursive capture is active");
            let global_index = self
                .capture_global_owner_index(active)
                .expect("split recursive capture has suspended globals");
            self.environment_activations[active + 1]
                .caller
                .transfer_capture_locals_from(&mut completed, count);
            let globals = &mut self.environment_activations[global_index].caller;
            globals.publish_global_scope_from(&mut completed);
            if publish && changed {
                captured.lock().unwrap_or_else(|p| p.into_inner()).copy_global_scope_from(globals);
            }
            self.capture_storage_pool.recycle(completed);
            return;
        }
        if frame.globals == CapturedGlobals::RecursiveOwner {
            let active = self.active_capture_index(&captured).expect("recursive capture is active");
            let index = self
                .capture_global_owner_index(active)
                .expect("foreign recursive capture has a suspended global owner");
            let owner = &mut self.environment_activations[index].caller;
            completed.swap_capture_prefix(owner, count);
            if changed {
                owner.invalidate_capture_observation();
            }
            if publish && changed {
                captured.lock().unwrap_or_else(|p| p.into_inner()).copy_global_scope_from(owner);
            }
            self.capture_storage_pool.recycle(completed);
            return;
        }
        if frame.globals == CapturedGlobals::RecursiveCaller {
            completed.swap_capture_prefix(&mut self.env, count);
            if changed {
                self.env.invalidate_capture_observation();
            }
            if publish && changed {
                captured
                    .lock()
                    .unwrap_or_else(|p| p.into_inner())
                    .copy_global_scope_from(&self.env);
            }
            self.capture_storage_pool.recycle(completed);
            return;
        }
        if publish && changed {
            if let Some(index) = self.active_capture_index(&captured) {
                self.restore_active_capture(index, &completed);
            }
        }
        match frame.globals {
            CapturedGlobals::TaskCaller => {
                completed.swap_global_scope(&mut self.env);
                if changed {
                    self.env.invalidate_capture_observation();
                }
            }
            CapturedGlobals::TaskCapture if changed => {
                self.remember_task_capture_globals(&captured, &completed);
            }
            CapturedGlobals::TaskBridge if changed => {
                if let Some(bridge) = &self.vm_globals {
                    bridge
                        .lock()
                        .unwrap_or_else(|poisoned| poisoned.into_inner())
                        .copy_global_scope_from(&completed);
                }
            }
            _ => {}
        }
        if !publish || !changed {
            self.capture_storage_pool.recycle(completed);
            return;
        }
        {
            let mut owner = captured.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
            completed.publish_indexed_to(&mut owner);
            if self.task_cancellation.is_some() {
                owner.merge_task_capture_writes(&completed);
            } else if completed.has_live_capture() {
                owner.publish_global_scope_from(&mut completed);
            } else {
                completed = std::mem::replace(&mut *owner, completed);
            }
        }
        self.capture_storage_pool.recycle(completed);
    }

    fn enter_shared_environment(&mut self, environment: Environment) -> SuspendedEnvironment {
        self.invalidate_capture_observations();
        let mut caller = std::mem::replace(&mut self.env, environment);
        self.env.swap_global_scope(&mut caller);
        if self.environment_activations.is_empty() {
            SuspendedEnvironment::Untracked(caller)
        } else {
            self.environment_activations.push(EnvironmentActivation {
                publication_policy: 0,
                nested_spill_hint: Default::default(),
                insertion_bound: 0,
                capture: None,
                caller,
                globals: CapturedGlobals::Snapshot,
            });
            SuspendedEnvironment::Tracked
        }
    }

    fn leave_shared_environment(&mut self, suspended: SuspendedEnvironment) -> Environment {
        let mut caller = match suspended {
            SuspendedEnvironment::Untracked(caller) => caller,
            SuspendedEnvironment::Tracked => {
                let frame = self.environment_activations.pop().expect("shared activation exists");
                assert!(frame.capture.is_none());
                frame.caller
            }
        };
        self.env.swap_global_scope(&mut caller);
        std::mem::replace(&mut self.env, caller)
    }

    fn enter_global_call_environment(&mut self) -> GlobalCallEnvironment {
        if self.environment_activations.is_empty() {
            return GlobalCallEnvironment::Untracked(self.env.enter_global_function());
        }
        let environment = self.env.generator_environment(false);
        let suspended = self.enter_shared_environment(environment);
        assert!(matches!(suspended, SuspendedEnvironment::Tracked));
        self.env.push_scope();
        GlobalCallEnvironment::Tracked
    }

    fn leave_global_call_environment(&mut self, caller: GlobalCallEnvironment) {
        match caller {
            GlobalCallEnvironment::Untracked(caller) => self.env.leave_global_function(caller),
            GlobalCallEnvironment::Tracked => {
                self.leave_shared_environment(SuspendedEnvironment::Tracked);
            }
        }
    }

    /// Helper function to call a user-defined function with given arguments
    /// Used by higher-order functions like map, filter, reduce
    pub(crate) fn call_user_function(&mut self, func: &Value, args: &[Value]) -> Value {
        self.call_user_function_owned(func, args.to_vec())
    }

    pub(crate) fn call_user_function_owned(&mut self, func: &Value, args: Vec<Value>) -> Value {
        self.call_user_function_owned_named(func, args, None)
    }

    fn call_user_function_owned_named(
        &mut self,
        func: &Value,
        mut args: Vec<Value>,
        name: Option<&str>,
    ) -> Value {
        self.env.flush_indexed_publication();
        match func {
            Value::BytecodeFunction { .. } => {
                let capture_globals_checkpoint = self.capture_globals_checkpoint();
                let active_captures = self.publish_active_captures_for_bridge();
                let globals = self
                    .vm_globals
                    .clone()
                    .unwrap_or_else(|| Arc::new(Mutex::new(self.env.clone())));
                let result = crate::vm::VM::call_interpreter_callback(
                    func.clone(),
                    args,
                    globals,
                    self.capability_policy.clone(),
                    self.output.clone(),
                    self.task_cancellation.clone(),
                    self.task_capture_globals.clone(),
                    self.vm_jit_requested,
                    &mut self.module_loader,
                )
                .unwrap_or_else(Value::Error);
                self.refresh_active_captures_after_bridge(active_captures);
                self.restore_capture_globals_checkpoint(capture_globals_checkpoint);
                result
            }
            Value::GeneratorDef(params, body, captured) => {
                let arity = Self::function_arity("<anonymous generator>", params);
                if let Some(error) = self.validate_callable_arity(&arity, args.len()) {
                    return error;
                }

                self.create_generator(params, body, captured, &args)
            }
            Value::AsyncFunction(..) => match self.submit_language_task(func.clone(), args) {
                Ok(task) => task.completion.clone(),
                Err(error) => Value::Error(error),
            },
            Value::Function(params, body, captured_env) => {
                let body_ref = body.get();
                let arity = Self::function_arity(name.unwrap_or("<anonymous function>"), params);
                if let Some(error) = self.validate_callable_arity(&arity, args.len()) {
                    return error;
                }

                // Push function name to call stack
                let func_name = name
                    .map(str::to_owned)
                    .unwrap_or_else(|| format!("<function with {} params>", params.len()));
                self.call_stack.push(func_name);

                // Keep the captured owner alive even when the body cannot observe it.
                // Independent bodies use the normal isolated parameter/local scope.
                if let Some(closure_env_ref) = captured_env
                    .as_ref()
                    .filter(|_| !body_ref.can_skip_capture_setup(params, &args))
                {
                    self.enter_captured_function_environment(
                        closure_env_ref,
                        &body_ref,
                        params,
                        &args,
                    );
                    self.env.push_scope();
                    if let Some(name) = &body.lexical_name {
                        self.env.define(
                            name.clone(),
                            Value::Function(
                                params.clone(),
                                body.clone(),
                                Some(closure_env_ref.clone()),
                            ),
                        );
                    }

                    // Bind parameters to arguments
                    for (param, arg) in params.iter().zip(args.drain(..)) {
                        self.env.define(param.clone(), arg);
                    }

                    // Execute function body
                    if let Err(error) = self
                        .with_function_context(name.unwrap_or("<anonymous function>"), |interp| {
                            interp.eval_stmts(&body_ref)
                        })
                    {
                        self.env.pop_scope();
                        self.leave_captured_environment(false);
                        self.call_stack.pop();
                        return error;
                    }

                    // Get return value
                    let result = if let Some(Value::Return(val)) = self.return_value.clone() {
                        self.return_value = None; // Clear return value
                        *val
                    } else if let Some(Value::Error(msg)) = self.return_value.clone() {
                        // Propagate error - don't clear
                        Value::Error(msg)
                    } else if let Some(Value::ErrorObject { .. }) = self.return_value.clone() {
                        // Propagate error object - don't clear
                        self.return_value.clone().unwrap()
                    } else {
                        // No explicit return - function falls through to null
                        self.return_value = None;
                        Value::Null
                    };

                    // Pop the parameter scope
                    self.env.pop_scope();

                    // Update the captured environment with the modified state
                    self.leave_captured_environment(true);

                    // Pop from call stack
                    self.call_stack.pop();

                    result
                } else {
                    // Top-level function: hide unrelated caller-local scopes
                    let caller_scopes = self.enter_global_call_environment();

                    // Bind parameters to arguments
                    for (param, arg) in params.iter().zip(args.drain(..)) {
                        self.env.define(param.clone(), arg);
                    }

                    // Execute function body
                    if let Err(error) = self
                        .with_function_context(name.unwrap_or("<anonymous function>"), |interp| {
                            interp.eval_stmts(&body_ref)
                        })
                    {
                        self.leave_global_call_environment(caller_scopes);
                        self.call_stack.pop();
                        return error;
                    }

                    // Get return value
                    let result = if let Some(Value::Return(val)) = self.return_value.clone() {
                        self.return_value = None; // Clear return value
                        *val
                    } else if let Some(Value::Error(msg)) = self.return_value.clone() {
                        // Propagate error - don't clear
                        Value::Error(msg)
                    } else if let Some(Value::ErrorObject { .. }) = self.return_value.clone() {
                        // Propagate error object - don't clear
                        self.return_value.clone().unwrap()
                    } else {
                        // No explicit return - function falls through to null
                        self.return_value = None;
                        Value::Null
                    };

                    // Restore parent environment
                    self.leave_global_call_environment(caller_scopes);

                    // Pop from call stack
                    self.call_stack.pop();

                    result
                }
            }
            _ => Value::Int(0),
        }
    }

    /// Execute one async-function mapper invocation in an isolated interpreter.
    /// `parallel_map` uses this on bounded worker tasks so mapper state cannot
    /// race through a shared interpreter environment.
    pub(crate) fn execute_async_mapper_isolated(
        func: &Value,
        arg: Value,
        base_env: Environment,
        capability_policy: RuntimeCapabilityPolicy,
    ) -> Value {
        let Value::AsyncFunction(params, body, captured_env) = func else {
            return Value::Error("parallel_map async mapper is not an async function".to_string());
        };
        if params.len() != 1 {
            return Value::Error(format!(
                "parallel_map async mapper expects 1 parameter, got {}",
                params.len()
            ));
        }
        // A closure already captures its complete lexical environment. Keep its
        // binding metadata and snapshot isolation instead of flattening copies
        // into the caller and accidentally making immutable bindings mutable.
        let environment = if let Some(env_ref) = captured_env {
            env_ref.lock().unwrap_or_else(|poisoned| poisoned.into_inner()).clone()
        } else {
            base_env
        };
        let mut interpreter = Interpreter::with_environment(capability_policy, environment);
        interpreter.env.push_scope();
        interpreter.env.define(params[0].clone(), arg);
        if let Err(error) = interpreter.with_function_context("<parallel async mapper>", |interp| {
            interp.eval_stmts(&body.get())
        }) {
            return error;
        }
        match interpreter.return_value.take() {
            Some(Value::Return(value)) => *value,
            Some(value @ Value::Error(_)) | Some(value @ Value::ErrorObject { .. }) => value,
            _ => Value::Null,
        }
    }

    // Operator bodies execute in the current activation, but the caller's
    // publication proof says nothing about their selectors or mutation patterns.
    // Suspend that proof while keeping writes private until an actual observation
    // or call boundary requires publication.
    fn with_operator_context<T>(
        &mut self,
        callable_name: &str,
        body: impl FnOnce(&mut Self) -> T,
    ) -> Result<T, Value> {
        let depth = self.environment_activations.len();
        let saved = self.environment_activations.last_mut().map(|frame| {
            (
                std::mem::take(&mut frame.publication_policy),
                std::mem::take(&mut frame.nested_spill_hint),
                std::mem::take(&mut frame.insertion_bound),
            )
        });
        let result = self.with_function_context(callable_name, body);
        debug_assert_eq!(self.environment_activations.len(), depth);
        if let Some((policy, hint, bound)) = saved {
            let frame = &mut self.environment_activations[depth - 1];
            frame.publication_policy = policy;
            frame.nested_spill_hint = hint;
            frame.insertion_bound = bound;
        }
        result
    }

    /// Attempts to call an operator method on a struct value
    /// Returns Some(result) if the struct has the operator method, None otherwise
    fn try_call_operator_method(
        &mut self,
        struct_val: &Value,
        method_name: &str,
        other: &Value,
    ) -> Option<Value> {
        if let Value::Struct { name, fields } = struct_val {
            // Look up the struct definition to find the operator method
            if let Some(Value::StructDef { name: _, field_names: _, methods }) = self.env.get(name)
            {
                if let Some(Value::Function(params, body, _captured_env)) = methods.get(method_name)
                {
                    let arity = Self::struct_method_arity(name, method_name, params);
                    if let Some(error) = self.validate_callable_arity(&arity, 1) {
                        return Some(error);
                    }

                    // Create new scope for operator method call
                    self.env.push_scope();

                    // Check if method has 'self' as first parameter
                    let has_self_param = params.first().map(|p| p == "self").unwrap_or(false);

                    if has_self_param {
                        // Bind self to the struct instance
                        self.env.define("self".to_string(), struct_val.clone());

                        // Bind the other operand as the second parameter (after self)
                        if let Some(param_name) = params.get(1) {
                            self.env.define(param_name.clone(), other.clone());
                        }
                    } else {
                        // Backward compatibility: bind fields directly into scope
                        for (field_name, field_value) in fields.iter() {
                            self.env.define(field_name.clone(), field_value.clone());
                        }

                        // Bind the other operand as the first parameter
                        if let Some(param_name) = params.first() {
                            self.env.define(param_name.clone(), other.clone());
                        }
                    }

                    // Execute method body
                    if let Err(error) = self
                        .with_operator_context(&format!("{}.{}", name, method_name), |interp| {
                            interp.eval_stmts(&body.get())
                        })
                    {
                        self.env.pop_scope();
                        return Some(error);
                    }

                    let result = match self.return_value.take() {
                        Some(Value::Return(value)) => *value,
                        Some(value @ Value::Error(_)) | Some(value @ Value::ErrorObject { .. }) => {
                            value
                        }
                        _ => Value::Null,
                    };

                    // Restore parent environment
                    self.env.pop_scope();

                    return Some(result);
                }
            }
        }
        None
    }

    /// Attempts to call a unary operator method on a struct value
    /// Returns Some(result) if the struct has the operator method, None otherwise
    fn try_call_unary_operator_method(
        &mut self,
        struct_val: &Value,
        method_name: &str,
    ) -> Option<Value> {
        if let Value::Struct { name, fields } = struct_val {
            // Look up the struct definition to find the operator method
            if let Some(Value::StructDef { name: _, field_names: _, methods }) = self.env.get(name)
            {
                if let Some(Value::Function(params, body, _captured_env)) = methods.get(method_name)
                {
                    let arity = Self::struct_method_arity(name, method_name, params);
                    if let Some(error) = self.validate_callable_arity(&arity, 0) {
                        return Some(error);
                    }

                    // Create new scope for operator method call
                    self.env.push_scope();

                    // Check if method has 'self' as first (and only) parameter
                    let has_self_param = params.first().map(|p| p == "self").unwrap_or(false);

                    if has_self_param {
                        // Bind self to the struct instance
                        self.env.define("self".to_string(), struct_val.clone());
                    } else {
                        // Backward compatibility: bind fields directly into scope
                        for (field_name, field_value) in fields.iter() {
                            self.env.define(field_name.clone(), field_value.clone());
                        }
                    }

                    // Execute method body
                    if let Err(error) = self
                        .with_operator_context(&format!("{}.{}", name, method_name), |interp| {
                            interp.eval_stmts(&body.get())
                        })
                    {
                        self.env.pop_scope();
                        return Some(error);
                    }

                    let result = match self.return_value.take() {
                        Some(Value::Return(value)) => *value,
                        Some(value @ Value::Error(_)) | Some(value @ Value::ErrorObject { .. }) => {
                            value
                        }
                        _ => Value::Null,
                    };

                    // Restore parent environment
                    self.env.pop_scope();

                    return Some(result);
                }
            }
        }
        None
    }

    /// Matches a route pattern against a URL path, extracting path parameters
    /// Returns Some(HashMap) with extracted params if matched, None if no match
    fn match_route_pattern(pattern: &str, path: &str) -> Option<HashMap<String, String>> {
        let pattern_parts: Vec<&str> = pattern.split('/').collect();
        let path_parts: Vec<&str> = path.split('/').collect();

        // Must have same number of segments
        if pattern_parts.len() != path_parts.len() {
            return None;
        }

        let mut params = HashMap::new();

        for (pattern_part, path_part) in pattern_parts.iter().zip(path_parts.iter()) {
            if let Some(param_name) = pattern_part.strip_prefix(':') {
                // This is a path parameter - extract it
                params.insert(param_name.to_string(), path_part.to_string());
            } else if *pattern_part != *path_part {
                // Static segment doesn't match
                return None;
            }
        }

        Some(params)
    }

    pub(crate) fn http_stream_event_type(event: &Value) -> Option<&str> {
        let Value::Dict(fields) = event else {
            return None;
        };
        let Value::Str(kind) = fields.get("type")? else {
            return None;
        };
        Some(kind.as_str())
    }

    fn respond_incremental_http(
        &mut self,
        request: tiny_http::Request,
        status: u16,
        headers: HashMap<String, String>,
        stream: SharedHttpResponseStream,
        callback: Option<Box<Value>>,
    ) {
        use tiny_http::{Header, Response, StatusCode};

        let Some(parts) = stream.lock().unwrap_or_else(|poisoned| poisoned.into_inner()).take()
        else {
            let _ = request.respond(
                Response::from_string("Internal Server Error: streaming response already consumed")
                    .with_status_code(500),
            );
            return;
        };

        let mut response =
            Response::new(StatusCode(status), Vec::new(), parts.body, parts.content_length, None)
                .with_chunked_threshold(0);
        for (name, value) in headers {
            if matches!(
                name.to_ascii_lowercase().as_str(),
                "connection"
                    | "content-length"
                    | "keep-alive"
                    | "proxy-authenticate"
                    | "proxy-authorization"
                    | "te"
                    | "trailer"
                    | "transfer-encoding"
                    | "upgrade"
            ) {
                continue;
            }
            if let Ok(header) = Header::from_bytes(name.as_bytes(), value.as_bytes()) {
                response.add_header(header);
            }
        }

        let events = parts.events;
        let cancelled = parts.cancelled;
        let response_thread = std::thread::spawn(move || request.respond(response));

        while let Ok(event) = events.recv() {
            let terminal = matches!(
                Self::http_stream_event_type(&event),
                Some("complete" | "error" | "cancelled")
            );
            if let Some(callback) = callback.as_deref() {
                let callback_result = self.call_user_function(callback, &[event]);
                if matches!(
                    callback_result,
                    Value::Bool(false) | Value::Error(_) | Value::ErrorObject { .. }
                ) {
                    cancelled.store(true, Ordering::Release);
                }
            }
            if terminal {
                break;
            }
        }

        let _ = response_thread.join();
    }

    pub(crate) fn routed_upload_request_fields(
        method: &str,
        path: &str,
        raw_path: &str,
        peer_address: &str,
        peer_ip: &str,
        peer_port: i64,
        query_params: &HashMap<String, String>,
        decoded_query_params: &HashMap<String, String>,
        raw_query: &str,
        path_params: &HashMap<String, String>,
        headers: &[tiny_http::Header],
        declared_body_length: Option<usize>,
    ) -> DictMap {
        let mut fields = DictMap::default();
        fields.insert("method".into(), Value::Str(Arc::new(method.to_string())));
        fields.insert("path".into(), Value::Str(Arc::new(path.to_string())));
        fields.insert("raw_path".into(), Value::Str(Arc::new(raw_path.to_string())));
        fields.insert("peer_address".into(), Value::Str(Arc::new(peer_address.to_string())));
        fields.insert("peer_ip".into(), Value::Str(Arc::new(peer_ip.to_string())));
        fields.insert("peer_port".into(), Value::Int(peer_port));
        fields.insert(
            "peer_transport".into(),
            Value::Str(Arc::new(if peer_address.is_empty() {
                "unknown".to_string()
            } else {
                "tcp".to_string()
            })),
        );
        fields.insert(
            "declared_body_bytes".into(),
            declared_body_length.map_or(Value::Null, |value| Value::Int(value as i64)),
        );
        let mut params = DictMap::default();
        for (key, value) in path_params {
            params.insert(Arc::from(key.as_str()), Value::Str(Arc::new(value.clone())));
        }
        fields.insert("params".into(), Value::Dict(Arc::new(params)));
        let mut query = DictMap::default();
        for (key, value) in query_params {
            query.insert(Arc::from(key.as_str()), Value::Str(Arc::new(value.clone())));
        }
        fields.insert("query".into(), Value::Dict(Arc::new(query)));
        let mut decoded_query = DictMap::default();
        for (key, value) in decoded_query_params {
            decoded_query.insert(Arc::from(key.as_str()), Value::Str(Arc::new(value.clone())));
        }
        fields.insert("query_decoded".into(), Value::Dict(Arc::new(decoded_query)));
        fields.insert("query_string".into(), Value::Str(Arc::new(raw_query.to_string())));
        let mut header_fields = DictMap::default();
        for header in headers {
            header_fields.insert(
                header.field.as_str().to_string().into(),
                Value::Str(Arc::new(header.value.as_str().to_string())),
            );
        }
        fields.insert("headers".into(), Value::Dict(Arc::new(header_fields)));
        fields
    }

    /// Starts an HTTP server with registered routes
    fn start_http_server(
        &mut self,
        host: &str,
        port: u16,
        routes: Vec<(String, String, Value)>,
        upload_routes: Vec<crate::interpreter::HttpUploadRoute>,
    ) -> Value {
        use tiny_http::{Response, Server};
        if let Err(error) =
            self.require_capability(NativeCapability::NetworkServer, "http_server.listen")
        {
            return error;
        }
        if !upload_routes.is_empty() {
            for capability in
                [NativeCapability::FilesystemWrite, NativeCapability::FilesystemDelete]
            {
                if let Err(error) = self.require_capability(capability, "http_server.route_upload")
                {
                    return error;
                }
            }
        }

        println!("Starting HTTP server on {}:{}...", host, port);

        let server = match Server::http_with_read_timeout(
            format!("{}:{}", host, port),
            http_request_utils::routed_http_read_timeout(),
        ) {
            Ok(s) => s,
            Err(e) => return Value::Error(format!("Failed to start server: {}", e)),
        };

        println!("Server listening on http://{}:{}", host, port);
        println!("Press Ctrl+C to stop");

        let maximum_in_flight = http_request_utils::routed_http_max_in_flight();
        let in_flight = Arc::new(AtomicUsize::new(0));
        http_request_utils::install_routed_http_shutdown_handler();

        // Main server loop
        loop {
            if http_request_utils::routed_http_shutdown_requested() {
                break;
            }
            let mut request = match server
                .recv_timeout(http_request_utils::routed_http_accept_poll_interval())
            {
                Ok(Some(request)) => request,
                Ok(None) => continue,
                Err(error) => return Value::Error(format!("HTTP server receive failed: {error}")),
            };
            let method = request.method().to_string();
            let request_url = request.url().to_string();
            let peer_address = request.remote_addr().map(ToString::to_string).unwrap_or_default();
            let peer_ip =
                request.remote_addr().map(|address| address.ip().to_string()).unwrap_or_default();
            let peer_port =
                request.remote_addr().map(|address| i64::from(address.port())).unwrap_or(0);
            let (url_path, query_params, decoded_query_params, raw_query) =
                http_request_utils::split_http_path_and_query_with_decoded(&request_url);

            let mut matched_upload: Option<(
                crate::interpreter::HttpUploadRoute,
                HashMap<String, String>,
            )> = None;
            for route in &upload_routes {
                if method == route.method && url_path == route.path {
                    matched_upload = Some((route.clone(), HashMap::new()));
                    break;
                }
            }
            if matched_upload.is_none() {
                for route in &upload_routes {
                    if method == route.method && route.path.contains(':') {
                        if let Some(params) = Self::match_route_pattern(&route.path, &url_path) {
                            matched_upload = Some((route.clone(), params));
                            break;
                        }
                    }
                }
            }

            if let Some((upload_route, path_params)) = matched_upload {
                let declared_body_length = request.body_length();
                let mut req_fields = Self::routed_upload_request_fields(
                    &method,
                    &url_path,
                    &request_url,
                    &peer_address,
                    &peer_ip,
                    peer_port,
                    &query_params,
                    &decoded_query_params,
                    &raw_query,
                    &path_params,
                    request.headers(),
                    declared_body_length,
                );
                req_fields
                    .insert("body_mode".into(), Value::Str(Arc::new("preflight".to_string())));
                let authorization = self.call_user_function(
                    &upload_route.authorize,
                    &[Value::Dict(Arc::new(req_fields.clone()))],
                );
                match authorization {
                    Value::Bool(true) => {}
                    Value::Bool(false) => {
                        let _ = request
                            .respond(Response::from_string("Forbidden").with_status_code(403));
                        continue;
                    }
                    Value::HttpResponse { status, body, headers } => {
                        let mut response = Response::from_data(body).with_status_code(status);
                        for (key, value) in headers {
                            if let Ok(header) =
                                tiny_http::Header::from_bytes(key.as_bytes(), value.as_bytes())
                            {
                                response = response.with_header(header);
                            }
                        }
                        let _ = request.respond(response);
                        continue;
                    }
                    _ => {
                        let _ = request.respond(
                            Response::from_string("Internal Server Error").with_status_code(500),
                        );
                        continue;
                    }
                }

                let spool = match http_request_utils::spool_bounded_http_request_body(
                    request.as_reader(),
                    declared_body_length,
                    &upload_route.spool_directory,
                    upload_route.max_body_bytes,
                ) {
                    Ok(spool) => spool,
                    Err(http_request_utils::HttpRequestBodyError::TooLarge) => {
                        let _ = request.respond(
                            Response::from_string("Payload Too Large").with_status_code(413),
                        );
                        continue;
                    }
                    Err(http_request_utils::HttpRequestBodyError::TimedOut) => {
                        let _ = request.respond(
                            Response::from_string("Request Timeout").with_status_code(408),
                        );
                        continue;
                    }
                    Err(http_request_utils::HttpRequestBodyError::ReadFailed) => {
                        let _ = request
                            .respond(Response::from_string("Bad Request").with_status_code(400));
                        continue;
                    }
                    Err(http_request_utils::HttpRequestBodyError::InvalidSpoolPolicy) => {
                        let _ = request.respond(
                            Response::from_string("Internal Server Error").with_status_code(500),
                        );
                        continue;
                    }
                    Err(http_request_utils::HttpRequestBodyError::SpoolFailed) => {
                        let _ = request.respond(
                            Response::from_string("Insufficient Storage").with_status_code(507),
                        );
                        continue;
                    }
                };
                let mut artifact = DictMap::default();
                artifact.insert(
                    "path".into(),
                    Value::Str(Arc::new(spool.path.to_string_lossy().to_string())),
                );
                artifact.insert("bytes".into(), Value::Int(spool.bytes as i64));
                artifact.insert("sha256".into(), Value::Str(Arc::new(spool.sha256.clone())));
                artifact.insert(
                    "schema_version".into(),
                    Value::Str(Arc::new("kujo.http.upload-artifact.v1".to_string())),
                );
                req_fields
                    .insert("body_mode".into(), Value::Str(Arc::new("private_spool".to_string())));
                req_fields.insert("body_artifact".into(), Value::Dict(Arc::new(artifact)));
                let result = self.call_user_function(
                    &upload_route.handler,
                    &[Value::Dict(Arc::new(req_fields))],
                );
                if http_request_utils::cleanup_routed_http_upload(&spool.path).is_err() {
                    let _ = request.respond(
                        Response::from_string("Internal Server Error").with_status_code(500),
                    );
                    continue;
                }
                match result {
                    Value::HttpResponse { status, body, headers } => {
                        let mut response = Response::from_data(body).with_status_code(status);
                        for (key, value) in headers {
                            if let Ok(header) =
                                tiny_http::Header::from_bytes(key.as_bytes(), value.as_bytes())
                            {
                                response = response.with_header(header);
                            }
                        }
                        let _ = request.respond(response);
                    }
                    Value::HttpStreamingResponse { status, headers, stream, callback } => {
                        self.respond_incremental_http(request, status, headers, stream, callback);
                    }
                    _ => {
                        let _ = request.respond(
                            Response::from_string("Internal Server Error").with_status_code(500),
                        );
                    }
                }
                continue;
            }

            // Read body first (before any response handling)
            let declared_body_length = request.body_length();
            let body_bytes = match http_request_utils::read_bounded_http_request_body_bytes(
                request.as_reader(),
                declared_body_length,
            ) {
                Ok(body) => body,
                Err(http_request_utils::HttpRequestBodyError::TooLarge) => {
                    let response = Response::from_string("Payload Too Large").with_status_code(413);
                    let _ = request.respond(response);
                    continue;
                }
                Err(http_request_utils::HttpRequestBodyError::TimedOut) => {
                    let response = Response::from_string("Request Timeout").with_status_code(408);
                    let _ = request.respond(response);
                    continue;
                }
                Err(http_request_utils::HttpRequestBodyError::ReadFailed) => {
                    let response = Response::from_string("Bad Request").with_status_code(400);
                    let _ = request.respond(response);
                    continue;
                }
                Err(
                    http_request_utils::HttpRequestBodyError::InvalidSpoolPolicy
                    | http_request_utils::HttpRequestBodyError::SpoolFailed,
                ) => {
                    let response =
                        Response::from_string("Internal Server Error").with_status_code(500);
                    let _ = request.respond(response);
                    continue;
                }
            };
            let body_content = String::from_utf8_lossy(&body_bytes).to_string();

            // Find matching route (supports path parameters like /:code)
            // Exact matches take priority over parameterized routes
            let mut matched_handler: Option<(&Value, HashMap<String, String>)> = None;

            // First pass: look for exact matches
            for (route_method, route_path, handler) in &routes {
                if method == *route_method && url_path == *route_path {
                    matched_handler = Some((handler, HashMap::new()));
                    break;
                }
            }

            // Second pass: if no exact match, try parameterized routes
            if matched_handler.is_none() {
                for (route_method, route_path, handler) in &routes {
                    if method != *route_method {
                        continue;
                    }
                    // Only try parameterized matching for routes with ':'
                    if route_path.contains(':') {
                        if let Some(path_params) = Self::match_route_pattern(route_path, &url_path)
                        {
                            matched_handler = Some((handler, path_params));
                            break;
                        }
                    }
                }
            }

            if let Some((handler, path_params)) = matched_handler {
                // Create params dict for request object
                let mut params_dict = DictMap::default();
                for (key, value) in &path_params {
                    params_dict
                        .insert(Arc::from(key.as_str()), Value::Str(Arc::new(value.clone())));
                }

                // Create request object as a Dict (not Struct) so has_key() and bracket access work
                let mut req_fields = DictMap::default();
                req_fields.insert("method".into(), Value::Str(Arc::new(method.clone())));
                req_fields.insert("path".into(), Value::Str(Arc::new(url_path.clone())));
                req_fields.insert("raw_path".into(), Value::Str(Arc::new(request_url.clone())));
                req_fields.insert("body".into(), Value::Str(Arc::new(body_content.clone())));
                req_fields.insert("body_bytes".into(), Value::bytes(body_bytes.clone()));
                req_fields.insert("params".into(), Value::Dict(Arc::new(params_dict)));
                req_fields
                    .insert("peer_address".into(), Value::Str(Arc::new(peer_address.clone())));
                req_fields.insert("peer_ip".into(), Value::Str(Arc::new(peer_ip.clone())));
                req_fields.insert("peer_port".into(), Value::Int(peer_port));
                req_fields.insert(
                    "peer_transport".into(),
                    Value::Str(Arc::new(if peer_address.is_empty() {
                        "unknown".to_string()
                    } else {
                        "tcp".to_string()
                    })),
                );

                // Extract query params from URL
                let mut query_dict = DictMap::default();
                for (key, value) in &query_params {
                    query_dict.insert(Arc::from(key.as_str()), Value::Str(Arc::new(value.clone())));
                }
                req_fields.insert("query".into(), Value::Dict(Arc::new(query_dict)));

                let mut decoded_query_dict = DictMap::default();
                for (key, value) in &decoded_query_params {
                    decoded_query_dict
                        .insert(Arc::from(key.as_str()), Value::Str(Arc::new(value.clone())));
                }
                req_fields
                    .insert("query_decoded".into(), Value::Dict(Arc::new(decoded_query_dict)));
                req_fields.insert("query_string".into(), Value::Str(Arc::new(raw_query.clone())));

                // Extract headers from request
                let mut headers_dict = DictMap::default();
                let mut header_values = DictMap::default();
                for header in request.headers() {
                    let header_name = header.field.as_str().to_string();
                    let header_value = header.value.as_str().to_string();
                    let values = header_values
                        .entry(header_name.to_ascii_lowercase().into())
                        .or_insert_with(|| Value::Array(Arc::new(Vec::new())));
                    if let Value::Array(values) = values {
                        Arc::make_mut(values).push(Value::Str(Arc::new(header_value.clone())));
                    }
                    headers_dict.insert(header_name.into(), Value::Str(Arc::new(header_value)));
                }
                req_fields.insert("headers".into(), Value::Dict(Arc::new(headers_dict)));
                req_fields.insert("header_values".into(), Value::Dict(Arc::new(header_values)));

                let req_obj = Value::Dict(Arc::new(req_fields));

                let Some(permit) = http_request_utils::try_acquire_routed_http_permit(
                    &in_flight,
                    maximum_in_flight,
                ) else {
                    let _ = request.respond(
                        Response::from_string("Service Unavailable")
                            .with_status_code(503)
                            .with_header(
                                tiny_http::Header::from_bytes(
                                    b"Retry-After".as_slice(),
                                    b"1".as_slice(),
                                )
                                .expect("static Retry-After header is valid"),
                            ),
                    );
                    continue;
                };
                let handler = handler.clone();
                let capability_policy = self.capability_policy.clone();
                let output = self.output.clone();
                std::thread::spawn(move || {
                    let _permit = permit;
                    let mut worker = Interpreter::with_capability_policy(capability_policy);
                    worker.output = output;
                    let result = worker.call_user_function(&handler, &[req_obj]);
                    match result {
                        Value::HttpResponse { status, body, headers } => {
                            let mut response = Response::from_data(body).with_status_code(status);
                            for (key, value) in headers {
                                if let Ok(header) =
                                    tiny_http::Header::from_bytes(key.as_bytes(), value.as_bytes())
                                {
                                    response = response.with_header(header);
                                }
                            }
                            let _ = request.respond(response);
                        }
                        Value::HttpStreamingResponse { status, headers, stream, callback } => {
                            worker.respond_incremental_http(
                                request, status, headers, stream, callback,
                            );
                        }
                        Value::Null => {
                            let _ =
                                request.respond(Response::from_string("OK").with_status_code(200));
                        }
                        _ => {
                            let _ = request.respond(
                                Response::from_string("Internal Server Error")
                                    .with_status_code(500),
                            );
                        }
                    }
                });
                continue;
            }

            let _ = request.respond(Response::from_string("Not Found").with_status_code(404));
        }

        if !http_request_utils::wait_for_routed_http_handlers(in_flight.as_ref()) {
            return Value::Error("HTTP server shutdown grace period expired".to_string());
        }

        Value::Int(0)
    }
    /// Calls a native built-in function
    fn call_native_function(&mut self, name: &str, args: &[Expr]) -> Value {
        // Evaluate all arguments
        let arg_values: Vec<Value> = args.iter().map(|arg| self.eval_expr(arg)).collect();
        if let Some(error) = arg_values.iter().find(|value| Self::is_error_value(value)) {
            return error.clone();
        }

        // Delegate to the implementation that works with Values
        self.call_native_function_impl(name, &arg_values)
    }

    /// Implementation of native function calling with pre-evaluated Value arguments
    /// This is used both by call_native_function (after evaluating Expr args)
    /// and by the VM (which already has Value args)
    pub fn call_native_function_impl(&mut self, name: &str, arg_values: &[Value]) -> Value {
        self.env.flush_indexed_publication();
        // Delegate to the native_functions module dispatcher
        native_functions::call_native_function(self, name, arg_values)
    }

    /// Helper method to check if two values are equal (for Set operations)
    fn values_equal(a: &Value, b: &Value) -> bool {
        Value::equals(a, b)
    }

    fn undefined_variable(name: &str) -> Value {
        Value::Error(format!("Undefined variable: {}", name))
    }

    fn is_error_value(value: &Value) -> bool {
        matches!(value, Value::Error(_) | Value::ErrorObject { .. })
    }

    fn set_return_if_error(&mut self, value: &Value) -> bool {
        if Self::is_error_value(value) {
            self.return_value = Some(value.clone());
            true
        } else {
            false
        }
    }

    fn value_type_name(value: &Value) -> &'static str {
        match value {
            Value::Int(_) => "int",
            Value::Float(_) => "float",
            Value::Bool(_) => "bool",
            Value::Str(_) => "string",
            Value::Secret(_) => "secret",
            Value::Array(_) => "array",
            value if value.dictionary_len().is_some() => "dict",
            Value::Struct { .. } => "struct",
            Value::Function(..) => "function",
            Value::NativeFunction(_) => "native_function",
            Value::Null => "null",
            Value::Error(_) | Value::ErrorObject { .. } => "error",
            _ => "value",
        }
    }

    fn invalid_binary_operation(op: &str, left: &Value, right: &Value) -> Value {
        Value::Error(format!(
            "Invalid binary operation: {} {} {}",
            Self::value_type_name(left),
            op,
            Self::value_type_name(right)
        ))
    }

    fn invalid_unary_operation(op: &str, value: &Value) -> Value {
        Value::Error(format!("Invalid unary operation: {} {}", op, Self::value_type_name(value)))
    }

    fn index_value(object: &Value, index: &Value) -> Value {
        if object.dictionary_len().is_some() {
            return match index {
                Value::Str(key) => object.dictionary_get(key).unwrap_or_else(|| {
                    Value::Error(format!("Missing map key: {:?}", key.as_ref()))
                }),
                Value::Int(index) => dictionary_publication::with_integer_key(*index, |key| {
                    object
                        .dictionary_get(key)
                        .unwrap_or_else(|| Value::Error(format!("Missing map key: {index}")))
                }),
                _ => Value::Error("Invalid index operation".into()),
            };
        }
        match (object, index) {
            (Value::Array(arr), Value::Int(i)) => {
                let idx = if *i < 0 { (arr.len() as i64) + *i } else { *i };
                if idx < 0 {
                    Value::Error(format!("Index out of bounds: {}", i))
                } else {
                    arr.get(idx as usize)
                        .cloned()
                        .unwrap_or_else(|| Value::Error(format!("Index out of bounds: {}", i)))
                }
            }
            (Value::Array(arr), Value::Float(i)) => {
                if !i.is_finite() {
                    return Value::Error("Invalid index operation".to_string());
                }
                let idx = *i as i64;
                let resolved = if idx < 0 { (arr.len() as i64) + idx } else { idx };
                if resolved < 0 {
                    Value::Error(format!("Index out of bounds: {}", i))
                } else {
                    arr.get(resolved as usize)
                        .cloned()
                        .unwrap_or_else(|| Value::Error(format!("Index out of bounds: {}", i)))
                }
            }
            (Value::Str(s), Value::Int(i)) => {
                let idx = if *i < 0 { (string_access::len(s) as i64) + *i } else { *i };
                if idx < 0 {
                    Value::Error(format!("Index out of bounds: {}", i))
                } else {
                    string_access::char_at(s, idx)
                        .map(|c| Value::Str(Arc::new(c.to_string())))
                        .unwrap_or_else(|| Value::Error(format!("Index out of bounds: {}", i)))
                }
            }
            (Value::Str(s), Value::Float(i)) => {
                if !i.is_finite() {
                    return Value::Error("Invalid index operation".to_string());
                }
                let idx = *i as i64;
                let resolved = if idx < 0 { (string_access::len(s) as i64) + idx } else { idx };
                if resolved < 0 {
                    Value::Error(format!("Index out of bounds: {}", i))
                } else {
                    string_access::char_at(s, resolved)
                        .map(|c| Value::Str(Arc::new(c.to_string())))
                        .unwrap_or_else(|| Value::Error(format!("Index out of bounds: {}", i)))
                }
            }
            (Value::Bytes(bytes), Value::Int(i)) => {
                let idx = if *i < 0 { (bytes.len() as i64) + *i } else { *i };
                if idx < 0 {
                    Value::Error(format!("Index out of bounds: {}", i))
                } else {
                    bytes
                        .get(idx as usize)
                        .copied()
                        .map(|byte| Value::Int(byte as i64))
                        .unwrap_or_else(|| Value::Error(format!("Index out of bounds: {}", i)))
                }
            }
            (Value::Bytes(bytes), Value::Float(i)) => {
                if !i.is_finite() {
                    return Value::Error("Invalid index operation".to_string());
                }
                let idx = *i as i64;
                let resolved = if idx < 0 { (bytes.len() as i64) + idx } else { idx };
                if resolved < 0 {
                    Value::Error(format!("Index out of bounds: {}", i))
                } else {
                    bytes
                        .get(resolved as usize)
                        .copied()
                        .map(|byte| Value::Int(byte as i64))
                        .unwrap_or_else(|| Value::Error(format!("Index out of bounds: {}", i)))
                }
            }
            (Value::Dict(map), Value::Str(key)) => map
                .get(key.as_str())
                .cloned()
                .unwrap_or_else(|| Value::Error(format!("Missing map key: {:?}", key.as_ref()))),
            (Value::Dict(map), Value::Int(key)) => map
                .get(key.to_string().as_str())
                .cloned()
                .unwrap_or_else(|| Value::Error(format!("Missing map key: {}", key))),
            _ => Value::Error("Invalid index operation".to_string()),
        }
    }

    fn assign_index(&mut self, object: &Expr, index: &Expr, value: &Value) -> Value {
        let index_value = self.eval_expr(index);
        if Self::is_error_value(&index_value) {
            return index_value;
        }

        let container_name = match object {
            Expr::Identifier(name) => name.as_str(),
            _ => return Value::Error("Complex index assignment not yet supported".to_string()),
        };

        // Index evaluation has completed. A visible pending dictionary already
        // proves the target's type and writable binding; rejecting its key does
        // not require materializing the pending updates.
        if self.env.pending_dictionary_visible(container_name)
            && !matches!(index_value, Value::Int(_) | Value::Str(_))
        {
            return Value::Error("Invalid index assignment: unsupported map key type".into());
        }

        let allow_multi_key =
            self.environment_activations.last().is_some_and(|frame| frame.allow_multi_key());
        if self.env.try_defer_index_write_with_policy(
            container_name,
            &index_value,
            value,
            allow_multi_key,
            self.environment_activations.last().map_or(0, |frame| frame.insertion_bound),
            self.environment_activations.last().is_some_and(|frame| frame.allow_boxed_array()),
            self.environment_activations.last().map_or(0, |frame| frame.array_batch_capacity()),
        ) {
            return Value::Null;
        }

        let mut assignment_error: Option<String> = None;
        let index_clone = index_value.clone();
        let value_clone = value.clone();

        let mutate_result =
            self.env.mutate_checked_runtime(container_name, |container| match container {
                Value::Bytes(bytes) => {
                    assignment_error =
                        assignment::write_byte(bytes, &index_clone, &value_clone).err();
                }
                Value::Array(arr) => {
                    let idx = match &index_clone {
                        Value::Int(i) => *i,
                        _ => {
                            assignment_error = Some(
                                "Invalid index assignment: unsupported array index type"
                                    .to_string(),
                            );
                            return;
                        }
                    };

                    let arr_mut = Arc::make_mut(arr);
                    let resolved = if idx < 0 { (arr_mut.len() as i64) + idx } else { idx };
                    if resolved < 0 || resolved as usize >= arr_mut.len() {
                        assignment_error = Some(format!("Index out of bounds: {}", idx));
                        return;
                    }

                    arr_mut[resolved as usize] = value_clone.clone();
                }
                other
                    if other.dictionary_len().is_some()
                        && !matches!(index_clone, Value::Int(_) | Value::Str(_)) =>
                {
                    assignment_error =
                        Some("Invalid index assignment: unsupported map key type".into());
                }
                Value::Dict(dict) => {
                    let key = Self::stringify_value(&index_clone);
                    Arc::make_mut(dict).insert(key.into(), value_clone.clone());
                }
                other if other.dictionary_len().is_some() => {
                    let mut dict: DictMap = Value::map_entries(other)
                        .expect("dictionary entries")
                        .into_iter()
                        .map(|(key, value)| (Arc::from(key), value))
                        .collect();
                    dict.insert(Self::stringify_value(&index_clone).into(), value_clone.clone());
                    *other = Value::Dict(Arc::new(dict));
                }
                _ => {
                    assignment_error = Some("Invalid index assignment".to_string());
                }
            });

        if let Err(error) = mutate_result {
            return Value::Error(error);
        }

        if let Some(error) = assignment_error {
            return Value::Error(error);
        }

        Value::Null
    }

    fn assign_evaluated(&mut self, target: &Expr, val: &Value) -> Value {
        match target {
            Expr::IndexAccess { object, .. } | Expr::FieldAccess { object, .. }
                if !matches!(&**object, Expr::Identifier(_)) =>
            {
                self.assign_path(target, val.clone())
            }
            Expr::Identifier(name) => match self.env.assign_checked(name.clone(), val.clone()) {
                Ok(()) => Value::Null,
                Err(error) => Value::Error(error),
            },
            Expr::IndexAccess { object, index } => {
                self.assign_index(object.as_ref(), index.as_ref(), val)
            }
            Expr::FieldAccess { object, field } => self.assign_member(object.as_ref(), field, val),
            _ => Value::Error("Invalid assignment target".to_string()),
        }
    }

    fn try_append_assignment(&mut self, target: &Expr, rhs: &Expr) -> Option<Value> {
        let Expr::Call { function, args } = rhs else { return None };
        let Expr::Identifier(function) = function.as_ref() else { return None };
        if args.len() != 2 {
            return None;
        }
        let (name, expressions) = assignment::split_target(target).ok()?;
        // Interpreter calls resolve the callable before evaluating arguments.
        let Some(Value::NativeFunction(native)) = self.env.get(function) else { return None };
        if !matches!(native.as_str(), "push" | "append" | "concat") {
            return None;
        }
        let values: Vec<Value> = args.iter().map(|arg| self.eval_expr(arg)).collect();
        if let Some(error) = values.iter().find(|v| Self::is_error_value(v)) {
            return Some(error.clone());
        }
        if native == "concat"
            && (!matches!((&values[0], &values[1]), (Value::Bytes(_), Value::Bytes(_)))
                || (matches!(expressions.as_slice(), [assignment::AccessExpr::Field(_)])
                    && !matches!(self.env.get(name), Some(Value::Struct { .. }))))
        {
            let value = self.call_native_function_impl(&native, &values);
            return Some(if Self::is_error_value(&value) {
                value
            } else {
                self.assign_evaluated(target, &value)
            });
        }
        if !expressions.is_empty() {
            if !matches!(values.first(), Some(Value::Array(_))) && native != "concat" {
                return Some(self.call_native_function_impl(&native, &values));
            }
            let mut path = Vec::new();
            for access in expressions {
                path.push(match access {
                    assignment::AccessExpr::Field(field) => assignment::Access::Field(field.into()),
                    assignment::AccessExpr::Index(index) => {
                        let value = self.eval_expr(index);
                        if Self::is_error_value(&value) {
                            return Some(value);
                        }
                        assignment::Access::Index(value)
                    }
                });
            }
            let mut values = values.into_iter();
            let original = values.next().unwrap();
            let item = values.next().unwrap();
            let mut error = None;
            let result = self.env.mutate_checked_runtime(name, |root| {
                error = if native == "concat" {
                    assignment::concat_bytes_path(root, &path, original, item, None).err()
                } else {
                    assignment::append_path(root, &path, original, item, None).err()
                };
            });
            return Some(match result.err().or(error) {
                Some(error) => Value::Error(error),
                None => Value::Null,
            });
        }
        let target = name;
        let mut values = values.into_iter();
        let mut original = values.next();
        let mut item = values.next();
        let mut appended = false;
        // No callbacks run while borrowing the destination. A callback that
        // reassigned it during argument evaluation forces ordinary call semantics.
        let _ = self.env.mutate_checked_runtime(target, |root| {
            appended = if native == "concat" {
                assignment::concat_bytes_rebinding(root, &mut original, item.as_ref().unwrap())
            } else {
                assignment::append_rebinding(root, &mut original, &mut item)
            };
        });
        if appended {
            return Some(Value::Null);
        }
        let value = self.call_native_function_impl(&native, &[original.unwrap(), item.unwrap()]);
        if Self::is_error_value(&value) {
            return Some(value);
        }
        Some(match self.env.assign_checked(target.to_string(), value) {
            Ok(()) => Value::Null,
            Err(error) => Value::Error(error),
        })
    }

    fn try_string_append_assignment(&mut self, target: &Expr, rhs: &Expr) -> Option<Value> {
        let Expr::Identifier(name) = target else { return None };
        let Expr::BinaryOp { left, op, right } = rhs else { return None };
        if op != "+" || !matches!(left.as_ref(), Expr::Identifier(source) if source == name) {
            return None;
        }
        if matches!(right.as_ref(), Expr::Int(_) | Expr::Float(_) | Expr::Bool(_) | Expr::None) {
            return None;
        }
        if !matches!(self.env.get(name), Some(Value::Str(_))) {
            return None;
        }
        let original = self.eval_expr(left);
        if Self::is_error_value(&original) {
            return Some(original);
        }
        let suffix = self.eval_expr(right);
        if Self::is_error_value(&suffix) {
            return Some(suffix);
        }
        let mut original = Some(original);
        let mut appended = false;
        let _ = self.env.mutate_checked_runtime(name, |root| {
            appended = assignment::concat_string_rebinding(root, &mut original, &suffix);
        });
        if appended {
            return Some(Value::Null);
        }
        let result = self.binary_op_value(original.as_ref().unwrap(), op, &suffix);
        Some(if Self::is_error_value(&result) {
            result
        } else {
            self.assign_evaluated(target, &result)
        })
    }

    fn try_owned_call_assignment(&mut self, target: &Expr, rhs: &Expr) -> Option<Value> {
        let Expr::Identifier(name) = target else { return None };
        let Expr::Call { function, args } = rhs else { return None };
        let Expr::Identifier(function_name) = function.as_ref() else { return None };
        if !matches!(args.first(), Some(Expr::Identifier(source)) if source == name) {
            return None;
        }
        let scope = self.ownership_scope?;
        if self.ownership_catches != 0 {
            return None;
        }
        // Function lookup precedes argument evaluation in the interpreter.
        let callable = self.env.get(function_name)?;
        if !matches!(callable, Value::Function(..)) {
            return None;
        }
        self.call_stack.push(function_name.clone());
        let values: Vec<Value> = args.iter().map(|arg| self.eval_expr(arg)).collect();
        self.call_stack.pop();
        if let Some(error) = values.iter().find(|value| Self::is_error_value(value)) {
            return Some(error.clone());
        }
        self.env.release_rebound_local(name, scope, &values[0]);
        let result = self.call_user_function_owned_named(&callable, values, Some(function_name));
        if Self::is_error_value(&result) {
            return Some(result);
        }
        Some(match self.env.assign_checked(name.clone(), result) {
            Ok(()) => Value::Null,
            Err(error) => Value::Error(error),
        })
    }

    fn try_nested_publication_read(&self, object: &Expr, index: &Expr) -> Option<Value> {
        use nested_publication::RowKey;
        let root = match object {
            Expr::FieldAccess { object, .. } | Expr::IndexAccess { object, .. } => object,
            _ => return None,
        };
        let mut root = root.as_ref();
        while let Expr::FieldAccess { object, .. } | Expr::IndexAccess { object, .. } = root {
            root = object;
        }
        let Expr::Identifier(name) = root else { return None };
        if !self.env.pending_nested_visible(name) {
            return None;
        }
        // Only lookup/literal indices (including checked integer negation)
        // can bypass the ordinary root snapshot.
        // Calls and other expressions retain their original evaluation order.
        if let Expr::String(key) = index {
            return self.read_nested_at(object, name, RowKey::String(key));
        }
        let index = match index {
            Expr::Int(index) => *index,
            Expr::Identifier(index) if index == name => return None,
            Expr::Identifier(index) => match self.env.get(index) {
                Some(Value::Int(index)) => index,
                Some(Value::Str(key)) => {
                    return self.read_nested_at(object, name, RowKey::String(&key))
                }
                _ => return None,
            },
            Expr::UnaryOp { op, operand } if op == "-" => {
                let value = match operand.as_ref() {
                    Expr::Int(value) => *value,
                    // The pending root is a collection, never an integer.
                    // Looking it up here would materialize an extra snapshot
                    // before the ordinary unary evaluator handles that value.
                    Expr::Identifier(index_name) if index_name == name => return None,
                    Expr::Identifier(index_name) => match self.env.get(index_name) {
                        Some(Value::Int(value)) => value,
                        _ => return None,
                    },
                    _ => return None,
                };
                // Overflow and non-integer/operator cases must retain the
                // ordinary evaluator's diagnostics and evaluation order.
                value.checked_neg()?
            }
            _ => return None,
        };
        self.read_nested_at(object, name, RowKey::Integer(index))
    }

    fn pure_nested_selector<'a>(
        &'a self,
        expr: &'a Expr,
        root: &str,
    ) -> Option<nested_publication::RowKey<'a>> {
        use nested_publication::RowKey;
        match expr {
            Expr::Int(value) => Some(RowKey::Integer(*value)),
            Expr::String(value) => Some(RowKey::String(value)),
            Expr::Identifier(name) if name != root => {
                match self.env.nested_spill_proof_value(name)? {
                    Value::Int(value) => Some(RowKey::Integer(*value)),
                    Value::Str(value) => Some(RowKey::String(value)),
                    _ => None,
                }
            }
            Expr::UnaryOp { op, operand } if op == "-" => {
                let RowKey::Integer(value) = self.pure_nested_selector(operand, root)? else {
                    return None;
                };
                Some(RowKey::Integer(value.checked_neg()?))
            }
            _ => None,
        }
    }

    fn read_nested_at(
        &self,
        object: &Expr,
        name: &str,
        leaf: nested_publication::RowKey<'_>,
    ) -> Option<Value> {
        use nested_publication::RowKey;
        let parent = match object {
            Expr::FieldAccess { object, .. } | Expr::IndexAccess { object, .. } => object.as_ref(),
            _ => return None,
        };
        if !matches!(parent, Expr::Identifier(_)) {
            return self.env.nested_publication_read_expression(name, object, leaf, |expr| {
                self.pure_nested_selector(expr, name)
            });
        }
        let read = |owner| match leaf {
            RowKey::Integer(index) => self.env.nested_publication_read(name, owner, index),
            RowKey::String(key) => self.env.nested_dictionary_publication_read(name, owner, key),
            RowKey::Field(_) => None,
        };
        match object {
            Expr::FieldAccess { field, .. } => read(RowKey::Field(field)),
            Expr::IndexAccess { index: key, .. } => match key.as_ref() {
                Expr::String(key) => read(RowKey::String(key)),
                Expr::Int(key) => read(RowKey::Integer(*key)),
                Expr::UnaryOp { op, operand } if op == "-" => {
                    let key = match operand.as_ref() {
                        Expr::Int(key) => *key,
                        Expr::Identifier(key) if key == name => return None,
                        Expr::Identifier(key) => match self.env.get(key) {
                            Some(Value::Int(key)) => key,
                            _ => return None,
                        },
                        _ => return None,
                    };
                    read(RowKey::Integer(key.checked_neg()?))
                }
                // A pending collection cannot be a scalar row selector.
                // Leave its materialization to the ordinary evaluator.
                Expr::Identifier(key) if key == name => None,
                Expr::Identifier(key) => match self.env.get(key) {
                    Some(Value::Str(key)) => read(RowKey::String(&key)),
                    Some(Value::Int(key)) => read(RowKey::Integer(key)),
                    _ => None,
                },
                _ => None,
            },
            _ => None,
        }
    }

    fn assign_path(&mut self, target: &Expr, mut value: Value) -> Value {
        use assignment::{split_target, Access, AccessExpr};
        let (name, expressions) = match split_target(target) {
            Ok(path) => path,
            Err(error) => return Value::Error(error),
        };
        let mut path = Vec::with_capacity(expressions.len());
        for expression in expressions {
            path.push(match expression {
                AccessExpr::Index(index) => {
                    let index = self.eval_expr(index);
                    if Self::is_error_value(&index) {
                        return index;
                    }
                    Access::Index(index)
                }
                AccessExpr::Field(field) => Access::Field(field.to_string()),
            });
        }
        let allow_spill = self
            .environment_activations
            .last()
            .map_or_else(Default::default, |frame| frame.nested_spill_hint);
        let path = match self.env.try_defer_nested_write_with_batching(
            name,
            path,
            &mut value,
            allow_spill,
        ) {
            Ok(()) => return Value::Null,
            Err(path) => path,
        };
        let mut error = None;
        let result = self.env.mutate_checked_runtime(name, |root| {
            error = assignment::update_in_place(root, &path, value).err();
        });
        match result.err().or(error) {
            Some(error) => Value::Error(error),
            None => Value::Null,
        }
    }

    fn assign_member(&mut self, object: &Expr, field: &str, value: &Value) -> Value {
        let field_name = field.to_string();
        let value_clone = value.clone();

        match object {
            Expr::Identifier(name) => {
                let mut assignment_error: Option<String> = None;
                let mutate_result = self.env.mutate_checked_runtime(name.as_str(), |obj_value| {
                    if let Value::Struct { name: _, fields } = obj_value {
                        Arc::make_mut(fields).insert(field_name.clone(), value_clone.clone());
                    } else {
                        assignment_error = Some("Cannot set field on non-struct value".to_string());
                    }
                });

                if let Err(error) = mutate_result {
                    return Value::Error(error);
                }

                if let Some(error) = assignment_error {
                    return Value::Error(error);
                }

                Value::Null
            }
            _ => Value::Error("Complex field assignment not yet supported".to_string()),
        }
    }

    fn unary_op_value(&self, op: &str, value: &Value) -> Value {
        match (op, value) {
            ("-", Value::Int(n)) => match n.checked_neg() {
                Some(result) => Value::Int(result),
                None => Value::Error(format!("Integer overflow: -({})", n)),
            },
            ("-", Value::Float(n)) => Value::Float(-n),
            ("!", Value::Bool(b)) => Value::Bool(!b),
            _ => Self::invalid_unary_operation(op, value),
        }
    }

    fn binary_op_value(&self, left: &Value, op: &str, right: &Value) -> Value {
        if op == "&&" {
            return Value::Bool(left.is_truthy() && right.is_truthy());
        }
        if op == "||" {
            return Value::Bool(left.is_truthy() || right.is_truthy());
        }
        if op == "==" {
            return Value::Bool(Value::equals(left, right));
        }
        if op == "!=" {
            return Value::Bool(!Value::equals(left, right));
        }
        if matches!(op, "<" | ">" | "<=" | ">=") {
            return match Value::compare_order(left, op, right) {
                Ok(result) => Value::Bool(result),
                Err(error) => Value::Error(error),
            };
        }

        match (left, right) {
            (Value::Int(a), Value::Int(b)) => match op {
                "+" | "-" | "*" | "/" | "%" => match Value::checked_int_arithmetic(*a, op, *b) {
                    Ok(result) => Value::Int(result),
                    Err(error) => Value::Error(error),
                },
                _ => Self::invalid_binary_operation(op, left, right),
            },
            (Value::Float(a), Value::Float(b)) => match op {
                "+" | "-" | "*" | "/" | "%" => match Value::checked_float_arithmetic(*a, op, *b) {
                    Ok(result) => Value::Float(result),
                    Err(error) => Value::Error(error),
                },
                _ => Self::invalid_binary_operation(op, left, right),
            },
            (Value::Int(a), Value::Float(b)) => {
                let a_float = *a as f64;
                match op {
                    "+" | "-" | "*" | "/" | "%" => {
                        match Value::checked_float_arithmetic(a_float, op, *b) {
                            Ok(result) => Value::Float(result),
                            Err(error) => Value::Error(error),
                        }
                    }
                    _ => Self::invalid_binary_operation(op, left, right),
                }
            }
            (Value::Float(a), Value::Int(b)) => {
                let b_float = *b as f64;
                match op {
                    "+" | "-" | "*" | "/" | "%" => {
                        match Value::checked_float_arithmetic(*a, op, b_float) {
                            Ok(result) => Value::Float(result),
                            Err(error) => Value::Error(error),
                        }
                    }
                    _ => Self::invalid_binary_operation(op, left, right),
                }
            }
            (Value::Str(a), Value::Str(b)) => match op {
                "+" => {
                    let mut result = a.clone();
                    let result_str = Arc::make_mut(&mut result);
                    result_str.push_str(b.as_ref());
                    Value::Str(result)
                }
                _ => Self::invalid_binary_operation(op, left, right),
            },
            _ => Self::invalid_binary_operation(op, left, right),
        }
    }

    fn validate_callable_arity(
        &self,
        arity: &CallableArity,
        received_args: usize,
    ) -> Option<Value> {
        arity.validate(received_args).err().map(Value::Error)
    }

    fn function_arity(name: impl Into<String>, params: &[String]) -> CallableArity {
        CallableArity::exact(name, params.to_vec())
    }

    fn struct_method_arity(
        struct_name: &str,
        method_name: &str,
        params: &[String],
    ) -> CallableArity {
        let has_self = params.first().map(|p| p == "self").unwrap_or(false);
        let external_params: Vec<String> =
            if has_self { params.iter().skip(1).cloned().collect() } else { params.to_vec() };
        CallableArity::exact(format!("{}.{}", struct_name, method_name), external_params)
    }

    fn create_struct_generator_method(
        &self,
        receiver: Value,
        struct_name: &str,
        fields: &HashMap<String, Value>,
        method_name: &str,
        params: &[String],
        body: &LeakyFunctionBody,
        captured: &Option<Arc<Mutex<Environment>>>,
        args: &[Value],
    ) -> Value {
        let arity = Self::struct_method_arity(struct_name, method_name, params);
        if let Some(error) = self.validate_callable_arity(&arity, args.len()) {
            return error;
        }

        if params.first().is_some_and(|param| param == "self") {
            let mut bound_args = Vec::with_capacity(args.len() + 1);
            bound_args.push(receiver);
            bound_args.extend(args.iter().cloned());
            return self.create_generator(params, body, captured, &bound_args);
        }

        // Legacy methods without an explicit `self` parameter see receiver fields
        // as lexical bindings. Snapshot them into the owned continuation at method
        // invocation so later resumer scopes cannot affect generator behavior.
        let mut method_environment = captured.as_ref().map_or_else(
            || self.env.generator_environment(false),
            |environment| {
                environment
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .generator_environment(true)
            },
        );
        method_environment.push_scope();
        for (field_name, field_value) in fields {
            method_environment.define(field_name.clone(), field_value.clone());
        }
        let method_capture = Some(Arc::new(Mutex::new(method_environment)));
        self.create_generator(params, body, &method_capture, args)
    }

