/// Open, bounded, atomically published private-file spool state.
///
/// The live file is reachable only through a `Value::PrivateSpool` handle. If
/// the handle is dropped or explicitly aborted before publication, the
/// same-directory temporary file is removed.
pub struct PrivateSpoolState {
    pub file: Option<File>,
    pub destination: PathBuf,
    pub temp: PathBuf,
    pub mode: u32,
    pub max_bytes: u64,
    pub bytes_written: u64,
    pub hasher: sha2::Sha256,
}

impl Drop for PrivateSpoolState {
    fn drop(&mut self) {
        self.file.take();
        let _ = std::fs::remove_file(&self.temp);
    }
}

// Forward declaration - Environment is in a sibling module
use super::environment::Environment;

/// Hash map for integer-keyed dictionaries.
pub type IntDictMap = HashMap<i64, Value, BuildHasherDefault<NoHashHasher<i64>>>;

/// Dense vector for integer-keyed dictionaries with non-negative keys.
pub type DenseIntDict = Vec<Value>;

/// Dense vector for integer-keyed dictionaries with optional int values.
pub type DenseIntDictInt = Vec<Option<i64>>;

/// Dense vector for integer-keyed dictionaries with int values only.
pub type DenseIntDictIntFull = Vec<i64>;

/// Hash map for string-keyed dictionaries.
pub type DictMap = HashMap<Arc<str>, Value, BuildHasherDefault<AHasher>>;

/// One-shot parts of an incremental HTTP response.
///
/// The response body is consumed by the routed HTTP server while stream events
/// are dispatched to the Kujo callback on the interpreter/VM thread. Keeping
/// this state behind an `Option` makes a streaming response explicitly
/// single-use even though runtime values are cheaply cloneable.
pub struct HttpResponseStreamParts {
    pub body: Box<dyn std::io::Read + Send>,
    pub events: Receiver<Value>,
    pub cancelled: Arc<std::sync::atomic::AtomicBool>,
    pub content_length: Option<usize>,
}

pub type SharedHttpResponseStream = Arc<Mutex<Option<HttpResponseStreamParts>>>;

/// A routed HTTP upload that authorizes from request metadata before any body
/// bytes are accepted, then streams the body into a bounded private file.
#[derive(Clone)]
pub struct HttpUploadRoute {
    pub method: String,
    pub path: String,
    pub spool_directory: String,
    pub max_body_bytes: u64,
    pub authorize: Value,
    pub handler: Value,
}

/// Stores function bodies and drops deeply nested statement trees iteratively.
///
/// Function bodies can contain very deep nesting through statements like loops,
/// `if`, `match`, and nested function definitions. Rust's default drop is recursive
/// for this shape and can overflow the stack at shutdown or when large AST graphs
/// are released.
///
/// This container keeps existing call sites stable while replacing the old
/// leak-on-drop strategy with a non-recursive drop traversal.
pub struct LeakyFunctionBody {
    id: usize,
    pub(crate) lexical_name: Option<String>,
}

#[derive(Clone)]
struct FunctionBodyStorage {
    body: Vec<Stmt>,
    capture_independence: OnceLock<Option<super::capture_independence::Proof>>,
}

struct StoredFunctionBody {
    refs: usize,
    storage: Arc<FunctionBodyStorage>,
}

static FUNCTION_BODY_STORE: OnceLock<Mutex<HashMap<usize, StoredFunctionBody>>> = OnceLock::new();
static NEXT_FUNCTION_BODY_ID: AtomicUsize = AtomicUsize::new(1);

fn function_body_store() -> &'static Mutex<HashMap<usize, StoredFunctionBody>> {
    FUNCTION_BODY_STORE.get_or_init(|| Mutex::new(HashMap::new()))
}

impl Drop for FunctionBodyStorage {
    fn drop(&mut self) {
        let body = std::mem::take(&mut self.body);
        drop_stmt_tree_iterative(body);
    }
}

fn drop_stmt_tree_iterative(root: Vec<Stmt>) {
    let mut stack = root;

    while let Some(mut stmt) = stack.pop() {
        match &mut stmt {
            Stmt::FuncDef { body, .. }
            | Stmt::Loop { body, .. }
            | Stmt::For { body, .. }
            | Stmt::While { body, .. }
            | Stmt::Block(body)
            | Stmt::Spawn { body }
            | Stmt::Test { body, .. }
            | Stmt::TestSetup { body }
            | Stmt::TestTeardown { body } => {
                stack.extend(std::mem::take(body));
            }
            Stmt::Match { cases, default, .. } => {
                for (_, case_body) in std::mem::take(cases) {
                    stack.extend(case_body);
                }
                if let Some(default_body) = default.take() {
                    stack.extend(default_body);
                }
            }
            Stmt::If { then_branch, else_branch, .. } => {
                stack.extend(std::mem::take(then_branch));
                if let Some(else_body) = else_branch.take() {
                    stack.extend(else_body);
                }
            }
            Stmt::TryExcept { try_block, except_block, .. } => {
                stack.extend(std::mem::take(try_block));
                stack.extend(std::mem::take(except_block));
            }
            Stmt::Export { stmt } => {
                let inner_stmt = std::mem::replace(stmt, Box::new(Stmt::Block(Vec::new())));
                stack.push(*inner_stmt);
            }
            Stmt::StructDef { methods, .. } | Stmt::TestGroup { tests: methods, .. } => {
                stack.extend(std::mem::take(methods));
            }
            Stmt::Let { .. }
            | Stmt::Const { .. }
            | Stmt::Assign { .. }
            | Stmt::EnumDef { .. }
            | Stmt::ExprStmt(_)
            | Stmt::Return(_)
            | Stmt::Break
            | Stmt::Continue
            | Stmt::Import { .. } => {}
        }
    }
}

pub struct FunctionBodyRef {
    storage: Arc<FunctionBodyStorage>,
}

pub(super) fn is_capture_primitive(value: &Value) -> bool {
    matches!(
        value,
        Value::Int(_)
            | Value::Float(_)
            | Value::Bool(_)
            | Value::Str(_)
            | Value::Bytes(_)
            | Value::Null
    )
}

impl FunctionBodyRef {
    /// Boxed array payloads are profitable only when no later statement can
    /// force publication. This allocation-free shape check is independent of
    /// capture purity: RHS/index callbacks still disable admission normally.
    pub(super) fn can_defer_boxed_array(&self) -> bool {
        use crate::ast::Expr;
        let (assignment, result) = match self.storage.body.as_slice() {
            [assignment] => (assignment, None),
            [assignment, Stmt::Return(result)] => (assignment, result.as_ref()),
            _ => return false,
        };
        let Stmt::Assign { target: Expr::IndexAccess { object, .. }, .. } = assignment else {
            return false;
        };
        let Expr::Identifier(root) = object.as_ref() else { return false };
        match result {
            None => true,
            Some(Expr::Identifier(name)) => name != root,
            Some(Expr::Int(_) | Expr::Float(_) | Expr::String(_) | Expr::Bool(_) | Expr::None) => {
                true
            }
            _ => false,
        }
    }

    pub(super) fn can_batch_nested_dictionary_writes(
        &self,
        params: &[String],
        args: &[Value],
        env: &super::environment::Environment,
    ) -> super::nested_spill_proof::SpillPolicy {
        let Some(proof) = self
            .storage
            .capture_independence
            .get_or_init(|| super::capture_independence::analyze(&self.storage.body))
        else {
            return super::nested_spill_proof::SpillPolicy::default();
        };
        if proof.nested_spill_region() {
            let dictionary =
                super::nested_spill_proof::eligible(&self.storage.body, params, args, env);
            if dictionary.capacity != 0 {
                dictionary
            } else {
                super::row_spill_proof::eligible_policy(&self.storage.body, params, args, env)
            }
        } else {
            super::nested_spill_proof::SpillPolicy::default()
        }
    }

    pub(super) fn can_batch_dictionary_writes(
        &self,
        params: &[String],
        args: &[Value],
        env: &super::environment::Environment,
    ) -> bool {
        let Some(proof) = self
            .storage
            .capture_independence
            .get_or_init(|| super::capture_independence::analyze(&self.storage.body))
        else {
            return false;
        };
        !proof.read_only
            && proof.sparse_write_region()
            && args.iter().all(is_capture_primitive)
            && proof.required_parameters.iter().enumerate().all(|(index, name)| {
                proof.whole_value_mask & (1u32 << index) == 0
                    || params.iter().any(|param| param == name)
                    // Inspect the entered capture on every invocation. A captured
                    // primitive can become an operator-bearing value between calls.
                    // Borrowing also avoids materializing pending/live snapshots.
                    || env.nested_spill_proof_value(name).is_some_and(is_capture_primitive)
            })
    }

    pub(super) fn dictionary_insertion_bound(&self, params: &[String], args: &[Value]) -> u16 {
        let Some(Some(proof)) = self.storage.capture_independence.get() else { return 0 };
        match proof.insertion_bound {
            u8::MAX => {
                super::dictionary_insertion_proof::runtime_bound(&self.storage.body, params, args)
            }
            n => u16::from(n),
        }
    }

    pub(super) fn read_capture_proof(
        &self,
        args: &[Value],
    ) -> Option<&super::capture_independence::Proof> {
        let proof = self
            .storage
            .capture_independence
            .get_or_init(|| super::capture_independence::analyze(&self.storage.body))
            .as_ref()?;
        if !proof.read_only || (proof.primitive_arguments && !args.iter().all(is_capture_primitive))
        {
            return None;
        }
        Some(proof)
    }

    /// Cache syntax analysis with the immutable body, not an environment or
    /// callable's publicly constructible parameter list. Recheck actual parameter
    /// names and dynamic operand kinds on every invocation.
    pub(crate) fn can_skip_capture_setup(&self, params: &[String], args: &[Value]) -> bool {
        let Some(proof) = self
            .storage
            .capture_independence
            .get_or_init(|| super::capture_independence::analyze(&self.storage.body))
        else {
            return false;
        };
        // A struct stored in a local collection can later reach an operator
        // through an indexed read. Keep its lexical operator environment.
        !proof.constructs_struct_payload()
            && proof.required_parameters.iter().all(|name| params.iter().any(|param| param == name))
            && (!proof.primitive_arguments
                || args.iter().all(|value| {
                    matches!(
                        value,
                        Value::Int(_)
                            | Value::Float(_)
                            | Value::Bool(_)
                            | Value::Str(_)
                            | Value::Bytes(_)
                            | Value::Null
                    )
                }))
    }
}

impl Deref for FunctionBodyRef {
    type Target = Vec<Stmt>;

    fn deref(&self) -> &Self::Target {
        &self.storage.body
    }
}

impl Clone for LeakyFunctionBody {
    fn clone(&self) -> Self {
        let mut store = function_body_store().lock().unwrap();
        if let Some(entry) = store.get_mut(&self.id) {
            entry.refs += 1;
        }

        LeakyFunctionBody { id: self.id, lexical_name: self.lexical_name.clone() }
    }
}

impl Drop for LeakyFunctionBody {
    fn drop(&mut self) {
        let mut store = function_body_store().lock().unwrap();
        if let Some(entry) = store.get_mut(&self.id) {
            if entry.refs > 1 {
                entry.refs -= 1;
            } else {
                store.remove(&self.id);
            }
        }
    }
}

impl LeakyFunctionBody {
    pub fn new(body: Vec<Stmt>) -> Self {
        let id = NEXT_FUNCTION_BODY_ID.fetch_add(1, Ordering::Relaxed);
        let storage = Arc::new(FunctionBodyStorage { body, capture_independence: OnceLock::new() });

        let mut store = function_body_store().lock().unwrap();
        store.insert(id, StoredFunctionBody { refs: 1, storage });

        LeakyFunctionBody { id, lexical_name: None }
    }

    pub(crate) fn named(name: &str, body: Vec<Stmt>) -> Self {
        let mut function = Self::new(body);
        function.lexical_name = Some(name.to_owned());
        function
    }

    pub fn get(&self) -> FunctionBodyRef {
        let store = function_body_store().lock().unwrap();
        if let Some(entry) = store.get(&self.id) {
            FunctionBodyRef { storage: Arc::clone(&entry.storage) }
        } else {
            FunctionBodyRef {
                storage: Arc::new(FunctionBodyStorage {
                    body: Vec::new(),
                    capture_independence: OnceLock::new(),
                }),
            }
        }
    }

    pub(crate) fn same_identity(&self, other: &Self) -> bool {
        self.id == other.id
    }
}

#[cfg(test)]
mod tests {
    #[cfg(feature = "runtime-db")]
    use super::ConnectionPool;
    use super::{DictMap, LeakyFunctionBody, Value};
    use crate::ast::Stmt;
    #[cfg(feature = "runtime-db")]
    use std::collections::HashMap;
    use std::sync::Arc;
    #[cfg(feature = "runtime-db")]
    use std::sync::Barrier;

    fn deeply_nested_loop_stmt(depth: usize) -> Stmt {
        let mut current = Stmt::Break;
        for _ in 0..depth {
            current = Stmt::Loop { condition: None, body: vec![current] };
        }
        current
    }

    #[cfg(feature = "runtime-db")]
    fn queued_pool(timeout: i64) -> ConnectionPool {
        let mut config = HashMap::new();
        config.insert("min_connections".into(), Value::Int(1));
        config.insert("max_connections".into(), Value::Int(1));
        config.insert("acquisition_timeout_ms".into(), Value::Int(timeout));
        ConnectionPool::new("sqlite".into(), ":memory:".into(), config).unwrap()
    }

    #[cfg(feature = "runtime-db")]
    fn await_waiters(pool: &ConnectionPool, count: usize) {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        while pool.state.lock().unwrap().waiters.len() != count {
            assert!(std::time::Instant::now() < deadline, "waiter did not enqueue");
            std::thread::yield_now();
        }
    }

    #[cfg(feature = "runtime-db")]
    #[test]
    fn database_pool_serves_queued_callers_before_reacquisition() {
        let pool = Arc::new(queued_pool(2000));
        let held = pool.acquire().unwrap();
        let (tx, rx) = std::sync::mpsc::channel();
        let mut workers = Vec::new();
        for index in 0..8 {
            let p = Arc::clone(&pool);
            let tx = tx.clone();
            workers.push(std::thread::spawn(move || {
                let connection = p.acquire().unwrap();
                tx.send(index).unwrap();
                p.release(connection).unwrap();
            }));
            await_waiters(&pool, index + 1);
        }
        pool.release(held).unwrap();
        // A releasing thread must not repeatedly barge ahead of older waiters.
        let again = pool.acquire().unwrap();
        assert_eq!(rx.try_iter().collect::<Vec<_>>(), (0..8).collect::<Vec<_>>());
        pool.release(again).unwrap();
        for worker in workers {
            worker.join().unwrap();
        }
        assert_eq!(pool.stats()["acquire_timeouts"], 0);
        assert!(pool.state.lock().unwrap().waiters.is_empty());
    }

    #[cfg(feature = "runtime-db")]
    #[test]
    fn database_pool_slow_health_check_does_not_block_other_slots() {
        let mut config = HashMap::new();
        config.insert("min_connections".into(), Value::Int(2));
        config.insert("max_connections".into(), Value::Int(2));
        config.insert("health_check".into(), Value::Bool(true));
        config.insert("acquisition_timeout_ms".into(), Value::Int(2000));
        let pool =
            Arc::new(ConnectionPool::new("sqlite".into(), ":memory:".into(), config).unwrap());
        pool.warm_minimum().unwrap();
        let handle = match pool.state.lock().unwrap().available.front().unwrap().connection.clone()
        {
            super::DatabaseConnection::Sqlite(handle) => handle,
            _ => unreachable!(),
        };
        let native_lock = handle.lock().unwrap();
        let p = Arc::clone(&pool);
        let first = std::thread::spawn(move || {
            let c = p.acquire().unwrap();
            p.release(c).unwrap();
        });
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        while pool.state.lock().unwrap().available.len() != 1 {
            assert!(std::time::Instant::now() < deadline);
            std::thread::yield_now();
        }
        let p = Arc::clone(&pool);
        let (tx, rx) = std::sync::mpsc::channel();
        let second = std::thread::spawn(move || {
            let result = p.acquire();
            tx.send(result.is_ok()).unwrap();
            if let Ok(c) = result {
                p.release(c).unwrap();
            }
        });
        let independent = rx.recv_timeout(std::time::Duration::from_secs(1));
        drop(native_lock);
        first.join().unwrap();
        second.join().unwrap();
        assert_eq!(independent.unwrap(), true);
        assert_eq!(pool.stats()["available"], 2);
    }

    #[cfg(feature = "runtime-db")]
    #[test]
    fn database_pool_failed_connect_removes_admission_ticket() {
        let path = std::env::temp_dir()
            .join(format!(
                "kujo-missing-{}-{}",
                std::process::id(),
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap()
                    .as_nanos()
            ))
            .join("database.sqlite");
        let mut config = HashMap::new();
        config.insert("min_connections".into(), Value::Int(0));
        config.insert("max_connections".into(), Value::Int(1));
        let pool =
            ConnectionPool::new("sqlite".into(), path.to_string_lossy().into(), config).unwrap();
        for _ in 0..2 {
            assert!(pool.acquire().err().unwrap().contains("Failed to create SQLite"));
            assert!(pool.state.lock().unwrap().waiters.is_empty());
            assert_eq!(pool.stats()["total"], 0);
        }
        assert_eq!(pool.stats()["connection_errors"], 2);
    }

    #[cfg(feature = "runtime-db")]
    #[test]
    fn database_pool_timeout_removes_ticket_and_close_wakes_waiter() {
        let pool = Arc::new(queued_pool(100));
        let held = pool.acquire().unwrap();
        assert!(pool.acquire().err().unwrap().contains("deadline exceeded"));
        assert!(pool.state.lock().unwrap().waiters.is_empty());
        pool.release(held).unwrap();
        let held = pool.acquire().unwrap();
        pool.release(held).unwrap();
        let pool = Arc::new(queued_pool(5000));
        let held = pool.acquire().unwrap();
        let p = Arc::clone(&pool);
        let (tx, rx) = std::sync::mpsc::channel();
        let worker = std::thread::spawn(move || {
            tx.send(p.acquire().err()).unwrap();
        });
        await_waiters(&pool, 1);
        pool.close();
        assert_eq!(
            rx.recv_timeout(std::time::Duration::from_secs(1)).unwrap().as_deref(),
            Some("database pool is closed")
        );
        worker.join().unwrap();
        pool.release(held).unwrap();
        assert_eq!(pool.stats()["total"], 0);
        assert!(pool.state.lock().unwrap().waiters.is_empty());
    }

    #[test]
    fn function_body_retains_statements() {
        let body = LeakyFunctionBody::new(vec![Stmt::Break, Stmt::Continue]);
        assert_eq!(2, body.get().len());
    }

    #[test]
    fn cloned_function_body_can_be_dropped_multiple_times() {
        let body = LeakyFunctionBody::new(vec![Stmt::Break]);
        let clone = body.clone();

        drop(clone);
        drop(body);
    }

    #[test]
    fn drops_deeply_nested_function_body_without_recursion_overflow() {
        let body = LeakyFunctionBody::new(vec![deeply_nested_loop_stmt(20000)]);
        drop(body);
    }

    #[test]
    fn cloned_handles_share_same_function_body_storage() {
        let body = LeakyFunctionBody::new(vec![Stmt::Break, Stmt::Continue]);
        let clone = body.clone();

        assert_eq!(body.get().len(), clone.get().len());
    }

    #[cfg(feature = "runtime-db")]
    #[test]
    fn database_pool_reserves_capacity_atomically() {
        let path = std::env::temp_dir().join(format!(
            "kujo_pool_capacity_{}_{}.sqlite",
            std::process::id(),
            std::thread::current().name().unwrap_or("test")
        ));
        let mut config = HashMap::new();
        config.insert("min_connections".to_string(), Value::Int(0));
        config.insert("max_connections".to_string(), Value::Int(1));
        config.insert("acquisition_timeout_ms".to_string(), Value::Int(100));
        let pool = Arc::new(
            ConnectionPool::new("sqlite".to_string(), path.to_string_lossy().to_string(), config)
                .expect("pool should initialize"),
        );
        let barrier = Arc::new(Barrier::new(17));
        let mut workers = Vec::new();
        for _ in 0..16 {
            let pool = Arc::clone(&pool);
            let barrier = Arc::clone(&barrier);
            workers.push(std::thread::spawn(move || {
                barrier.wait();
                pool.acquire().ok()
            }));
        }
        barrier.wait();
        let connections = workers
            .into_iter()
            .filter_map(|worker| worker.join().expect("worker should not panic"))
            .collect::<Vec<_>>();
        assert_eq!(connections.len(), 1);
        assert_eq!(pool.stats().get("total"), Some(&1));
        drop(connections);
        pool.close();
        let _ = std::fs::remove_file(path);
    }

    #[cfg(feature = "runtime-db")]
    #[test]
    fn database_pool_discards_a_return_completed_after_close() {
        let mut config = HashMap::new();
        config.insert("min_connections".to_string(), Value::Int(0));
        config.insert("max_connections".to_string(), Value::Int(1));
        let pool = ConnectionPool::new("sqlite".to_string(), ":memory:".to_string(), config)
            .expect("pool should initialize");
        let connection = pool.acquire().expect("connection should be available");
        let created_at = pool
            .state
            .lock()
            .unwrap()
            .checked_out
            .remove(&super::connection_key(&connection))
            .expect("connection should be checked out");

        // Simulate close winning the race after reset, before the returned
        // connection can re-enter the available queue.
        pool.close();
        pool.return_reset_connection(connection, created_at).unwrap();
        let stats = pool.stats();
        assert_eq!(stats["available"], 0);
        assert_eq!(stats["total"], 0);
        assert_eq!(stats["closed"], 1);
    }

    #[test]
    fn value_truthiness_semantics_match_runtime_contract() {
        let mut non_empty_dict = DictMap::default();
        non_empty_dict.insert(Arc::<str>::from("k"), Value::Int(1));

        let falsey_values = vec![
            Value::Bool(false),
            Value::Null,
            Value::Int(0),
            Value::Float(0.0),
            Value::Str(Arc::new(String::new())),
            Value::Array(Arc::new(vec![])),
            Value::Dict(Arc::new(DictMap::default())),
        ];
        for value in falsey_values {
            assert!(!value.is_truthy(), "expected falsey value, got {:?}", value);
        }

        let truthy_values = vec![
            Value::Bool(true),
            Value::Int(-1),
            Value::Float(0.5),
            Value::Str(Arc::new("false".to_string())),
            Value::Array(Arc::new(vec![Value::Int(1)])),
            Value::Dict(Arc::new(non_empty_dict)),
        ];
        for value in truthy_values {
            assert!(value.is_truthy(), "expected truthy value, got {:?}", value);
        }
    }

    #[test]
    fn value_equals_supports_numeric_cross_type_and_nested_collections() {
        assert!(Value::equals(&Value::Int(1), &Value::Float(1.0)));
        assert!(!Value::equals(&Value::Int(1), &Value::Float(2.0)));

        let left_nested = Value::Array(Arc::new(vec![
            Value::Int(1),
            Value::Array(Arc::new(vec![Value::Int(2), Value::Int(3)])),
        ]));
        let right_nested = Value::Array(Arc::new(vec![
            Value::Int(1),
            Value::Array(Arc::new(vec![Value::Int(2), Value::Int(3)])),
        ]));
        assert!(Value::equals(&left_nested, &right_nested));

        let mut left_dict = DictMap::default();
        left_dict.insert(Arc::<str>::from("answer"), Value::Int(42));
        let mut right_dict = DictMap::default();
        right_dict.insert(Arc::<str>::from("answer"), Value::Int(42));
        assert!(Value::equals(
            &Value::Dict(Arc::new(left_dict)),
            &Value::Dict(Arc::new(right_dict))
        ));
    }

    #[test]
    fn value_equals_supports_function_and_native_identity() {
        let function_body = LeakyFunctionBody::new(vec![Stmt::Return(None)]);
        let same_function = Value::Function(vec!["x".to_string()], function_body.clone(), None);
        let same_function_alias =
            Value::Function(vec!["x".to_string()], function_body.clone(), None);
        let different_function = Value::Function(
            vec!["x".to_string()],
            LeakyFunctionBody::new(vec![Stmt::Return(None)]),
            None,
        );

        assert!(Value::equals(&same_function, &same_function_alias));
        assert!(!Value::equals(&same_function, &different_function));
        assert!(Value::equals(
            &Value::NativeFunction("print".to_string()),
            &Value::NativeFunction("print".to_string())
        ));
    }

    #[test]
    fn value_compare_order_rejects_unsupported_types() {
        let bool_error =
            Value::compare_order(&Value::Bool(true), "<", &Value::Bool(false)).unwrap_err();
        assert!(bool_error.contains("Invalid binary operation"));

        let mixed_error =
            Value::compare_order(&Value::Int(1), "<", &Value::Str(Arc::new("1".to_string())))
                .unwrap_err();
        assert!(mixed_error.contains("Invalid binary operation"));

        assert_eq!(
            Value::compare_order(
                &Value::Str(Arc::new("a".to_string())),
                "<",
                &Value::Str(Arc::new("b".to_string()))
            )
            .unwrap(),
            true
        );
    }
}

/// Database connection types
/// Infrastructure for database.rs stub module
#[cfg(feature = "runtime-db")]
pub struct RuntimeSafePostgresClient(Option<PostgresClient>);

#[cfg(feature = "runtime-db")]
impl RuntimeSafePostgresClient {
    pub fn new(client: PostgresClient) -> Self {
        Self(Some(client))
    }

    pub fn close(mut self) -> Result<(), postgres::Error> {
        let client = self.0.take().expect("PostgreSQL client is available");
        AsyncRuntime::run_runtime_safe_blocking(move || client.close())
    }
}

#[cfg(feature = "runtime-db")]
impl Deref for RuntimeSafePostgresClient {
    type Target = PostgresClient;

    fn deref(&self) -> &Self::Target {
        self.0.as_ref().expect("PostgreSQL client is available")
    }
}

#[cfg(feature = "runtime-db")]
impl DerefMut for RuntimeSafePostgresClient {
    fn deref_mut(&mut self) -> &mut Self::Target {
        self.0.as_mut().expect("PostgreSQL client is available")
    }
}

#[cfg(feature = "runtime-db")]
impl Drop for RuntimeSafePostgresClient {
    fn drop(&mut self) {
        if let Some(client) = self.0.take() {
            AsyncRuntime::run_runtime_safe_blocking(move || drop(client));
        }
    }
}

#[cfg(feature = "runtime-db")]
#[derive(Clone)]
pub enum DatabaseConnection {
