rows.each do |row|
 old=row.fetch('baseline');args=[probe]+old.fetch('argv').drop(1)
 out,err,status=Open3.capture3(*args);m=err.match(/requests=(\d+) requested_bytes=(\d+)/)
 raise out+err unless status.success?&&out==old.fetch('stdout')&&m
 current={argv:args,stdout:out,stderr:err,exit:status.exitstatus,requests:m[1].to_i,bytes:m[2].to_i}
 report[:rows]<<{report:row.fetch('report'),index:row.fetch('index'),baseline:old,candidate:current,passed:current[:requests]<=old.fetch('requests')&&current[:bytes]<=old.fetch('bytes')}
 write.call
end
raise 'probe drift' unless Digest::SHA256.file(probe).hexdigest==hash
manifest.each{|p,h|raise 'source drift' unless Digest::SHA256.file(p).hexdigest==h}
b.fetch('sources').each{|p,h|raise 'fixture drift' unless Digest::SHA256.file(p).hexdigest==h}
report[:status]=report[:rows].all?{|r|r[:passed]} ? 'passed' : 'failed';write.call
puts "Known regressions: #{report[:rows].count{|r|r[:passed]}}/116 passed"
exit(report[:status]=='passed' ? 0 : 1)

