+impl DictionaryBatchPublication {
+    fn new(name: Box<str>, base: Arc<DictMap>, bound: u16) -> Self {
+        debug_assert!(bound >= 2);
+        Self {
+            name,
+            base,
+            writes: CollectionWrites::with_capacity_and_hasher(
+                usize::from(bound),
+                Default::default(),
+            ),
+        }
+    }
