// File: src/interpreter/environment.rs
//
// Lexical scoping environment for variable management in the Kujo interpreter.
// Implements a stack of scopes where inner scopes shadow outer scopes.

use super::array_collection_publication::ArrayCollectionPublication;
use super::binding_map::BindingMap;
use super::dictionary_publication::{
    CollectionPayload, CollectionValue, DictionaryBatchPublication,
    DictionaryCollectionPublication, DictionaryManyPublication, DictionaryPairPublication,
    DictionaryPublication, DictionaryScalar,
};
use super::value::Value;
use std::collections::{HashMap, HashSet};
use std::sync::{Arc, Mutex, Weak};

#[derive(Clone, Debug)]
struct LiveCapture {
    owner: Weak<Mutex<Environment>>,
    limit: usize,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BindingKind {
    Mutable,
    LetImmutable,
    Const,
}

impl BindingKind {
    fn reassignment_error(self, name: &str) -> String {
        match self {
            BindingKind::Mutable => unreachable!("mutable bindings allow reassignment"),
            BindingKind::LetImmutable => {
                format!("Cannot reassign immutable let binding: {}", name)
            }
            BindingKind::Const => format!("Cannot reassign const binding: {}", name),
        }
    }

    fn mutation_error(self, name: &str) -> String {
        match self {
            BindingKind::Mutable => unreachable!("mutable bindings allow mutation"),
            BindingKind::LetImmutable => format!("Cannot mutate immutable let binding: {}", name),
            BindingKind::Const => format!("Cannot mutate const binding: {}", name),
        }
    }

    fn allows_mutation(self) -> bool {
        matches!(self, BindingKind::Mutable)
    }
}

// Most captured calls write zero or one binding. Keep that journal inline;
// promote to a hash set only when an invocation writes distinct bindings.
#[derive(Clone, Debug, Default)]
enum CaptureWrites {
    #[default]
    Empty,
    One((usize, String)),
    Many(HashSet<(usize, String)>),
    Indexed(super::indexed_publication::IndexedPublication),
    ArrayCollection(ArrayCollectionPublication<Box<CollectionValue>>),
    ArrayArray(ArrayCollectionPublication<Arc<Vec<Value>>>),
    ArrayMap(ArrayCollectionPublication<Arc<super::value::DictMap>>),
    ArrayMixed(Box<ArrayCollectionPublication<super::array_batch_publication::BatchValue>>),
    ArrayBatch(Box<super::array_batch_publication::ArrayBatchPublication>),
    Dictionary(DictionaryPublication),
    DictionaryFloat(DictionaryPublication<f64>),
    DictionaryBool(DictionaryPublication<bool>),
    DictionaryNull(DictionaryPublication<()>),
    DictionaryCollection(DictionaryCollectionPublication),
    DictionaryArray(DictionaryCollectionPublication<Arc<Vec<Value>>>),
    DictionaryMap(DictionaryCollectionPublication<Arc<super::value::DictMap>>),
    DictionaryMany(Box<DictionaryManyPublication>),
    DictionaryBatch(Box<DictionaryBatchPublication>),
    DictionaryPair(DictionaryPairPublication),
    Nested(super::nested_publication::NestedPublication),
}

#[cfg(test)]
#[test]
fn indexed_publication_candidate_fits_capture_storage_layout() {
    // Compare against the actual existing enum, including its discriminant and
    // enclosing Option. Payload-size comparison alone misses niche/layout costs.
    // Preserve the pre-integration enum layout, not just its largest payload.
    #[allow(dead_code)]
    enum Previous {
        Empty,
        One((usize, String)),
        Many(HashSet<(usize, String)>),
    }
    assert_eq!(std::mem::size_of::<Previous>(), std::mem::size_of::<CaptureWrites>());
    assert_eq!(std::mem::align_of::<Previous>(), std::mem::align_of::<CaptureWrites>());
    assert_eq!(
        std::mem::size_of::<Option<(usize, Previous)>>(),
        std::mem::size_of::<Option<(usize, CaptureWrites)>>()
    );
    #[allow(dead_code)]
    enum WithNestedCandidate {
        Empty,
        One((usize, String)),
        Many(HashSet<(usize, String)>),
        Indexed(super::indexed_publication::IndexedPublication),
        Dictionary(DictionaryPublication),
        Nested(super::nested_publication::NestedPublication),
    }
    assert_eq!(std::mem::size_of::<CaptureWrites>(), std::mem::size_of::<WithNestedCandidate>());
    assert_eq!(std::mem::align_of::<CaptureWrites>(), std::mem::align_of::<WithNestedCandidate>());
    assert_eq!(
        std::mem::size_of::<Option<(usize, CaptureWrites)>>(),
        std::mem::size_of::<Option<(usize, WithNestedCandidate)>>()
    );
}

impl CaptureWrites {
    fn array_collection_len(&self) -> Option<usize> {
        match self {
            Self::ArrayCollection(p) => Some(p.len()),
            Self::ArrayArray(p) => Some(p.len()),
            Self::ArrayMap(p) => Some(p.len()),
            Self::ArrayMixed(p) => Some(p.len()),
            Self::ArrayBatch(p) => Some(p.len()),
            _ => None,
        }
    }

    fn array_collection_matches(&self, index: usize) -> bool {
        match self {
            Self::ArrayCollection(p) => p.is_single() && p.matches_index(index),
            Self::ArrayArray(p) => p.is_single() && p.matches_index(index),
            Self::ArrayMap(p) => p.is_single() && p.matches_index(index),
            _ => false,
        }
    }

    fn array_collection_get(&self, index: usize) -> Option<Value> {
        match self {
            Self::ArrayCollection(p) => p.get(index),
            Self::ArrayArray(p) => p.get(index),
            Self::ArrayMap(p) => p.get(index),
            Self::ArrayMixed(p) => p.get(index),
            Self::ArrayBatch(p) => p.get(index),
            _ => None,
        }
    }

    fn with_array_collection(self, value: &Value) -> Self {
        macro_rules! convert {
            ($pending:expr) => {
                match value {
                    Value::Array(v) => Self::ArrayArray($pending.with_payload(v.clone())),
                    Value::Dict(v) => Self::ArrayMap($pending.with_payload(v.clone())),
                    _ => Self::ArrayCollection(
                        $pending.with_payload(Box::new(CollectionValue::from_value(value))),
                    ),
                }
            };
        }
        match self {
            Self::ArrayCollection(mut p) if !matches!(value, Value::Array(_) | Value::Dict(_)) => {
                **p.payload_mut() = CollectionValue::from_value(value);
                Self::ArrayCollection(p)
            }
            Self::ArrayCollection(p) => convert!(p),
            Self::ArrayArray(p) => convert!(p),
            Self::ArrayMap(p) => convert!(p),
            _ => unreachable!("admitted array collection"),
        }
    }

    fn dictionary_get(&self, key: &str) -> Option<Value> {
        match self {
            Self::Dictionary(pending) => pending.get(key),
            Self::DictionaryFloat(pending) => pending.get(key),
            Self::DictionaryBool(pending) => pending.get(key),
            Self::DictionaryNull(pending) => pending.get(key),
            Self::DictionaryCollection(pending) => pending.get(key),
            Self::DictionaryArray(pending) => pending.get(key),
            Self::DictionaryMap(pending) => pending.get(key),
            Self::DictionaryPair(pending) => pending.get(key),
            Self::DictionaryMany(pending) => pending.get(key),
            Self::DictionaryBatch(pending) => pending.get(key),
            _ => None,
        }
    }

    fn dictionary_can_record(
        &self,
        key: &str,
        value: &Value,
        allow_many: bool,
        insertion_bound: u16,
    ) -> bool {
        if let Self::DictionaryBatch(pending) = self {
            return allow_many && pending.can_record(key, value, insertion_bound);
        }
        if DictionaryCollectionPublication::supports(value) {
            macro_rules! admit {
                ($p:expr) => {
                    $p.matches_key(key) || (allow_many && $p.can_batch(key, insertion_bound))
                };
            }
            return match self {
                Self::Dictionary(p) => admit!(p),
                Self::DictionaryFloat(p) => admit!(p),
                Self::DictionaryBool(p) => admit!(p),
                Self::DictionaryNull(p) => admit!(p),
                Self::DictionaryCollection(p) => admit!(p),
                Self::DictionaryArray(p) => admit!(p),
                Self::DictionaryMap(p) => admit!(p),
                Self::DictionaryPair(p) => allow_many && p.can_batch(key, insertion_bound),
                Self::DictionaryMany(p) => allow_many && p.can_batch(key, insertion_bound),
                _ => false,
            };
        }
        match self {
            Self::Dictionary(pending) => {
                pending.matches_key(key)
                    || pending.can_pair(key, value)
                    || (allow_many
                        && (pending.contains_key(key) || pending.can_insert(insertion_bound)))
            }
            Self::DictionaryFloat(pending) => {
                pending.matches_key(key)
                    || pending.can_pair(key, value)
                    || (allow_many
                        && (pending.contains_key(key) || pending.can_insert(insertion_bound)))
            }
            Self::DictionaryBool(pending) => {
                pending.matches_key(key)
                    || pending.can_pair(key, value)
                    || (allow_many
                        && (pending.contains_key(key) || pending.can_insert(insertion_bound)))
            }
            Self::DictionaryNull(pending) => {
                pending.matches_key(key)
                    || pending.can_pair(key, value)
                    || (allow_many
                        && (pending.contains_key(key) || pending.can_insert(insertion_bound)))
            }
            Self::DictionaryCollection(pending) => {
                pending.matches_key(key) || (allow_many && pending.can_batch(key, insertion_bound))
            }
            Self::DictionaryArray(pending) => {
                pending.matches_key(key) || (allow_many && pending.can_batch(key, insertion_bound))
            }
            Self::DictionaryMap(pending) => {
                pending.matches_key(key) || (allow_many && pending.can_batch(key, insertion_bound))
            }
            Self::DictionaryMany(_) => allow_many,
            Self::DictionaryPair(pending) => pending.can_record(key, value) || allow_many,
            _ => false,
        }
    }

    fn prepare_dictionary(
        name: String,
        base: Arc<super::value::DictMap>,
        key: &str,
        value: &Value,
    ) -> Result<Self, (String, Arc<super::value::DictMap>)> {
        match value {
            Value::Int(value) => {
                DictionaryPublication::prepare(name, base, key, *value).map(Self::Dictionary)
            }
            Value::Float(value) => DictionaryPublication::prepare_scalar(name, base, key, *value)
                .map(Self::DictionaryFloat),
            Value::Bool(value) => DictionaryPublication::prepare_scalar(name, base, key, *value)
                .map(Self::DictionaryBool),
            Value::Null => {
                DictionaryPublication::prepare_scalar(name, base, key, ()).map(Self::DictionaryNull)
            }
            Value::Array(values) => {
                DictionaryCollectionPublication::prepare_payload(name, base, key, values.clone())
                    .map(Self::DictionaryArray)
            }
            Value::Dict(values) => {
                DictionaryCollectionPublication::prepare_payload(name, base, key, values.clone())
                    .map(Self::DictionaryMap)
            }
            value if DictionaryCollectionPublication::supports(value) => {
                DictionaryCollectionPublication::prepare(name, base, key, value)
                    .map(Self::DictionaryCollection)
            }
            _ => Err((name, base)),
        }
    }

    fn replace_dictionary_value<T: DictionaryScalar>(
        pending: DictionaryPublication<T>,
        value: &Value,
    ) -> Self {
        match value {
            Value::Int(value) => Self::Dictionary(pending.with_value(*value)),
            Value::Float(value) => Self::DictionaryFloat(pending.with_value(*value)),
            Value::Bool(value) => Self::DictionaryBool(pending.with_value(*value)),
            Value::Null => Self::DictionaryNull(pending.with_value(())),
            Value::Array(values) => {
                Self::DictionaryArray(pending.with_collection_payload(values.clone()))
            }
            Value::Dict(values) => {
                Self::DictionaryMap(pending.with_collection_payload(values.clone()))
            }
            value if DictionaryCollectionPublication::supports(value) => {
                Self::DictionaryCollection(pending.with_collection(value))
            }
            _ => unreachable!("admitted dictionary value"),
        }
    }

    fn replace_collection_value<T: CollectionPayload>(
        pending: DictionaryCollectionPublication<T>,
        value: &Value,
    ) -> Self {
        match value {
            Value::Int(value) => Self::Dictionary(pending.with_scalar(*value)),
            Value::Float(value) => Self::DictionaryFloat(pending.with_scalar(*value)),
            Value::Bool(value) => Self::DictionaryBool(pending.with_scalar(*value)),
            Value::Null => Self::DictionaryNull(pending.with_scalar(())),
            Value::Array(values) => Self::DictionaryArray(pending.with_payload(values.clone())),
            Value::Dict(values) => Self::DictionaryMap(pending.with_payload(values.clone())),
            value if DictionaryCollectionPublication::supports(value) => {
                Self::DictionaryCollection(pending.with_collection(value))
            }
            _ => unreachable!("admitted dictionary collection replacement"),
        }
    }

    fn with_dictionary_value(self, key: &str, value: &Value, bound: u16) -> Self {
        macro_rules! batch {
            ($p:expr) => {{
                let mut p = $p.into_batch(bound);
                p.record(key, value);
                Self::DictionaryBatch(Box::new(p))
            }};
        }
        match self {
            Self::Dictionary(pending) => {
                if pending.matches_key(key) {
                    Self::replace_dictionary_value(pending, value)
                } else if DictionaryCollectionPublication::supports(value) {
                    batch!(pending)
                } else if pending.can_pair(key, value) {
                    Self::DictionaryPair(pending.into_pair(key, value))
                } else {
                    Self::DictionaryMany(Box::new(pending.into_many(key, value)))
                }
            }
            Self::DictionaryFloat(pending) => {
                if pending.matches_key(key) {
                    Self::replace_dictionary_value(pending, value)
                } else if DictionaryCollectionPublication::supports(value) {
                    batch!(pending)
                } else if pending.can_pair(key, value) {
                    Self::DictionaryPair(pending.into_pair(key, value))
                } else {
                    Self::DictionaryMany(Box::new(pending.into_many(key, value)))
                }
            }
            Self::DictionaryBool(pending) => {
                if pending.matches_key(key) {
                    Self::replace_dictionary_value(pending, value)
                } else if DictionaryCollectionPublication::supports(value) {
                    batch!(pending)
                } else if pending.can_pair(key, value) {
                    Self::DictionaryPair(pending.into_pair(key, value))
                } else {
                    Self::DictionaryMany(Box::new(pending.into_many(key, value)))
                }
            }
            Self::DictionaryNull(pending) => {
                if pending.matches_key(key) {
                    Self::replace_dictionary_value(pending, value)
                } else if DictionaryCollectionPublication::supports(value) {
                    batch!(pending)
                } else if pending.can_pair(key, value) {
                    Self::DictionaryPair(pending.into_pair(key, value))
                } else {
                    Self::DictionaryMany(Box::new(pending.into_many(key, value)))
                }
            }
            Self::DictionaryArray(pending) => {
                if !pending.matches_key(key) {
                    return batch!(pending);
                }
                Self::replace_collection_value(pending, value)
            }
            Self::DictionaryMap(pending) => {
                if !pending.matches_key(key) {
                    return batch!(pending);
                }
                Self::replace_collection_value(pending, value)
            }
            Self::DictionaryCollection(mut pending) => {
                if !pending.matches_key(key) {
                    return batch!(pending);
                }
                if DictionaryCollectionPublication::supports(value)
                    && !matches!(value, Value::Array(_) | Value::Dict(_))
                {
                    pending.replace(value);
                    Self::DictionaryCollection(pending)
                } else {
                    Self::replace_collection_value(pending, value)
                }
            }
            Self::DictionaryPair(mut pending) => {
                if DictionaryCollectionPublication::supports(value) {
                    return batch!(pending);
                }
                if pending.can_record(key, value) {
                    pending.record(key, value);
                    Self::DictionaryPair(pending)
                } else {
                    let mut pending = pending.into_many();
                    pending.record(key, value);
                    Self::DictionaryMany(Box::new(pending))
                }
            }
            Self::DictionaryMany(mut pending) => {
                if DictionaryCollectionPublication::supports(value) {
                    return batch!(pending);
                }
                pending.record(key, value);
                Self::DictionaryMany(pending)
            }
            Self::DictionaryBatch(mut pending) => {
                pending.record(key, value);
                Self::DictionaryBatch(pending)
            }
            _ => unreachable!("admitted dictionary journal"),
        }
    }

    fn record(&mut self, index: usize, name: &str) {
        if matches!(self, Self::One((scope, existing)) if *scope == index && existing == name) {
            return;
        }
        self.insert((index, name.to_owned()));
    }

    fn insert(&mut self, write: (usize, String)) {
        match self {
            Self::Empty => *self = Self::One(write),
            Self::One(existing) if *existing == write => {}
            Self::One(_) => {
                let Self::One(previous) = std::mem::take(self) else { unreachable!() };
                *self = Self::Many(HashSet::from([previous, write]));
            }
            Self::Many(writes) => {
                writes.insert(write);
            }
            Self::Indexed(_)
            | Self::ArrayCollection(_)
            | Self::ArrayArray(_)
            | Self::ArrayMap(_)
            | Self::ArrayMixed(_)
            | Self::ArrayBatch(_)
            | Self::Dictionary(_)
            | Self::DictionaryFloat(_)
            | Self::DictionaryBool(_)
            | Self::DictionaryPair(_)
            | Self::DictionaryMany(_)
            | Self::DictionaryBatch(_)
            | Self::DictionaryNull(_)
            | Self::DictionaryCollection(_)
            | Self::DictionaryArray(_)
            | Self::DictionaryMap(_)
            | Self::Nested(_) => {
                unreachable!("private publication is not a task write journal")
            }
        }
    }

    fn iter(&self) -> impl Iterator<Item = &(usize, String)> {
        let (first, rest) = match self {
            Self::Empty
            | Self::Indexed(_)
            | Self::ArrayCollection(_)
            | Self::ArrayArray(_)
            | Self::ArrayMap(_)
            | Self::ArrayMixed(_)
            | Self::ArrayBatch(_)
            | Self::Dictionary(_)
            | Self::DictionaryFloat(_)
            | Self::DictionaryBool(_)
            | Self::DictionaryPair(_)
            | Self::DictionaryMany(_)
            | Self::DictionaryBatch(_)
            | Self::DictionaryNull(_)
            | Self::DictionaryCollection(_)
            | Self::DictionaryArray(_)
            | Self::DictionaryMap(_)
            | Self::Nested(_) => (None, None),
            Self::One(write) => (Some(write), None),
            Self::Many(writes) => (None, Some(writes)),
        };
        first.into_iter().chain(rest.into_iter().flat_map(|writes| writes.iter()))
    }

    fn extend(&mut self, writes: impl IntoIterator<Item = (usize, String)>) {
        for write in writes {
            self.insert(write);
        }
    }

    fn publication_name(&self) -> Option<&str> {
        match self {
            Self::Indexed(pending) => Some(pending.name()),
            Self::ArrayCollection(pending) => Some(pending.name()),
            Self::ArrayArray(pending) => Some(pending.name()),
            Self::ArrayMap(pending) => Some(pending.name()),
            Self::ArrayMixed(pending) => Some(pending.name()),
            Self::ArrayBatch(pending) => Some(pending.name()),
            Self::Dictionary(pending) => Some(pending.name()),
            Self::DictionaryFloat(pending) => Some(pending.name()),
            Self::DictionaryBool(pending) => Some(pending.name()),
            Self::DictionaryNull(pending) => Some(pending.name()),
            Self::DictionaryCollection(pending) => Some(pending.name()),
            Self::DictionaryArray(pending) => Some(pending.name()),
            Self::DictionaryMap(pending) => Some(pending.name()),
            Self::DictionaryPair(pending) => Some(pending.name()),
            Self::DictionaryMany(pending) => Some(pending.name()),
            Self::DictionaryBatch(pending) => Some(pending.name()),
            Self::Nested(pending) => Some(pending.name()),
            _ => None,
        }
    }

    fn publication_snapshot(&self) -> Option<Value> {
        match self {
            Self::Indexed(pending) => Some(pending.snapshot_value()),
            Self::ArrayCollection(pending) => Some(pending.snapshot_value()),
            Self::ArrayArray(pending) => Some(pending.snapshot_value()),
            Self::ArrayMap(pending) => Some(pending.snapshot_value()),
            Self::ArrayMixed(pending) => Some(pending.snapshot_value()),
            Self::ArrayBatch(pending) => Some(pending.snapshot_value()),
            Self::Dictionary(pending) => Some(pending.snapshot_value()),
            Self::DictionaryFloat(pending) => Some(pending.snapshot_value()),
            Self::DictionaryBool(pending) => Some(pending.snapshot_value()),
            Self::DictionaryNull(pending) => Some(pending.snapshot_value()),
            Self::DictionaryCollection(pending) => Some(pending.snapshot_value()),
            Self::DictionaryArray(pending) => Some(pending.snapshot_value()),
            Self::DictionaryMap(pending) => Some(pending.snapshot_value()),
            Self::DictionaryPair(pending) => Some(pending.snapshot_value()),
            Self::DictionaryMany(pending) => Some(pending.snapshot_value()),
            Self::DictionaryBatch(pending) => Some(pending.snapshot_value()),
            Self::Nested(pending) => Some(pending.snapshot_value()),
            _ => None,
        }
    }

    fn publish(self, owner: Option<&mut Value>) -> Option<(String, Value)> {
        match self {
            Self::Indexed(pending) => Some(pending.publish(owner)),
            Self::ArrayCollection(pending) => Some(pending.publish(owner)),
            Self::ArrayArray(pending) => Some(pending.publish(owner)),
            Self::ArrayMap(pending) => Some(pending.publish(owner)),
            Self::ArrayMixed(pending) => Some(pending.publish(owner)),
            Self::ArrayBatch(pending) => Some(pending.publish(owner)),
            Self::Dictionary(pending) => Some(pending.publish(owner)),
            Self::DictionaryFloat(pending) => Some(pending.publish(owner)),
            Self::DictionaryBool(pending) => Some(pending.publish(owner)),
            Self::DictionaryNull(pending) => Some(pending.publish(owner)),
            Self::DictionaryCollection(pending) => Some(pending.publish(owner)),
            Self::DictionaryArray(pending) => Some(pending.publish(owner)),
            Self::DictionaryMap(pending) => Some(pending.publish(owner)),
            Self::DictionaryPair(pending) => Some(pending.publish(owner)),
            Self::DictionaryMany(pending) => Some(pending.publish(owner)),
            Self::DictionaryBatch(pending) => Some(pending.publish(owner)),
            Self::Nested(pending) => Some(pending.publish(owner)),
