#[path="/Users/robertdevore/2026/Kujolang/kujo-repos/kujo/src/interpreter/capture_names.rs"]
mod capture_names;
use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering::SeqCst};
static ACTIVE:AtomicBool=AtomicBool::new(false);
static REQUESTS:AtomicUsize=AtomicUsize::new(0);
static BYTES:AtomicUsize=AtomicUsize::new(0);
struct Count;
unsafe impl GlobalAlloc for Count {
 unsafe fn alloc(&self,l:Layout)->*mut u8 {if ACTIVE.load(SeqCst){REQUESTS.fetch_add(1,SeqCst);BYTES.fetch_add(l.size(),SeqCst);}unsafe{System.alloc(l)}}
 unsafe fn dealloc(&self,p:*mut u8,l:Layout){unsafe{System.dealloc(p,l)}}
 unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8 {if ACTIVE.load(SeqCst){REQUESTS.fetch_add(1,SeqCst);BYTES.fetch_add(n,SeqCst);}unsafe{System.realloc(p,l,n)}}
}
#[global_allocator]static ALLOC:Count=Count;
fn counted<T>(f:impl FnOnce()->T)->(T,usize,usize){REQUESTS.store(0,SeqCst);BYTES.store(0,SeqCst);ACTIVE.store(true,SeqCst);let value=f();ACTIVE.store(false,SeqCst);(value,REQUESTS.load(SeqCst),BYTES.load(SeqCst))}
#[test]fn inline_names_remove_cold_metadata_allocations_without_heap_regression(){
 for input in [vec!["n","state"],vec!["long_capture_dependency_one","long_capture_dependency_two"]] {
  let (old,requests,bytes)=counted(||input.iter().map(|s|s.to_string()).collect::<Vec<_>>());
  let (new,nr,nb)=counted(||capture_names::CaptureNames::from_names(input.iter().copied()));
  assert_eq!(new.iter().collect::<Vec<_>>(),old.iter().map(String::as_str).collect::<Vec<_>>());
  if input[0]=="n"{assert_eq!((requests,bytes),(3,54));assert_eq!((nr,nb),(0,0));}else{assert_eq!((nr,nb),(requests,bytes));}
 }
}
